require('dotenv').config();
const db = require('../backend/config/database');

const laws = [
  // ===== INDIAN PENAL CODE (IPC) - 120 sections =====
  { act: "Indian Penal Code", section: "34", title: "Acts done by several persons in furtherance of common intention", content: "When a criminal act is done by several persons in furtherance of the common intention of all, each of such persons is liable for that act in the same manner as if it were done by him alone.", keywords: ["common intention", "joint liability", "group crime"] },
  { act: "Indian Penal Code", section: "107", title: "Abetment of a thing", content: "A person abets the doing of a thing who instigates any person to do that thing, or engages with one or more persons in any conspiracy for the doing of that thing, or intentionally aids by any act or illegal omission the doing of that thing.", keywords: ["abetment", "instigation", "conspiracy"] },
  { act: "Indian Penal Code", section: "120B", title: "Punishment of criminal conspiracy", content: "Whoever is a party to a criminal conspiracy to commit an offence punishable with death, imprisonment for life or rigorous imprisonment for two years or upwards shall be punished in the same manner as if he had abetted such offence.", keywords: ["criminal conspiracy", "conspiracy punishment"] },
  { act: "Indian Penal Code", section: "124A", title: "Sedition", content: "Whoever by words, either spoken or written, or by signs, or by visible representation, or otherwise, brings or attempts to bring into hatred or contempt, or excites or attempts to excite disaffection towards the Government established by law in India shall be punished with imprisonment for life and fine, or imprisonment up to three years and fine.", keywords: ["sedition", "anti-government", "disaffection"] },
  { act: "Indian Penal Code", section: "141", title: "Unlawful assembly", content: "An assembly of five or more persons is designated an unlawful assembly if the common object of the persons composing that assembly is to overawe by criminal force the Central or State Government or any public servant, or to resist the execution of any law or legal process.", keywords: ["unlawful assembly", "mob", "rioting"] },
  { act: "Indian Penal Code", section: "144", title: "Joining unlawful assembly armed with deadly weapon", content: "Whoever, being armed with any deadly weapon or with anything which used as a weapon of offence is likely to cause death, is a member of an unlawful assembly, shall be punished with imprisonment up to two years, or with fine, or with both.", keywords: ["armed assembly", "deadly weapon", "unlawful gathering"] },
  { act: "Indian Penal Code", section: "147", title: "Punishment for rioting", content: "Whoever is guilty of rioting shall be punished with imprisonment up to two years, or with fine, or with both.", keywords: ["rioting", "riot", "mob violence"] },
  { act: "Indian Penal Code", section: "148", title: "Rioting armed with deadly weapon", content: "Whoever is guilty of rioting, being armed with a deadly weapon or with anything which used as a weapon of offence is likely to cause death, shall be punished with imprisonment up to three years, or with fine, or with both.", keywords: ["armed rioting", "weapon riot"] },
  { act: "Indian Penal Code", section: "153A", title: "Promoting enmity between different groups", content: "Whoever by words, either spoken or written, or by signs or by visible representations or otherwise, promotes or attempts to promote, on grounds of religion, race, place of birth, residence, language, caste or community, disharmony or feelings of enmity, hatred or ill-will between different religious, racial, language or regional groups or castes or communities, shall be punished with imprisonment up to three years, or with fine, or with both.", keywords: ["hate speech", "communal hatred", "enmity", "religious hatred"] },
  { act: "Indian Penal Code", section: "166A", title: "Public servant disobeying direction under law", content: "Whoever, being a public servant, knowingly disobeys any direction of the law which prohibits him from requiring the attendance at any place of any person for the purpose of investigation into an offence or any other matter, or knowingly disobeys any other direction of the law regulating the manner in which he shall conduct such investigation, shall be punished with rigorous imprisonment up to two years and fine.", keywords: ["public servant", "disobedience", "police duty"] },
  { act: "Indian Penal Code", section: "170", title: "Personating a public servant", content: "Whoever pretends to hold any particular office as a public servant, knowing that he does not hold such office, or falsely personates any other person holding such office, shall be punished with imprisonment up to two years, or with fine, or with both.", keywords: ["impersonation", "fake officer", "public servant fraud"] },
  { act: "Indian Penal Code", section: "182", title: "False information to public servant", content: "Whoever gives to any public servant any information which he knows or believes to be false, intending thereby to cause such public servant to use the lawful power of such public servant to the injury or annoyance of any person, shall be punished with imprisonment up to six months, or with fine up to one thousand rupees, or with both.", keywords: ["false information", "false complaint", "fake report"] },
  { act: "Indian Penal Code", section: "191", title: "Giving false evidence", content: "Whoever, being legally bound by an oath or by an express provision of law to state the truth, or being bound by law to make a declaration upon any subject, makes any statement which is false, and which he either knows or believes to be false or does not believe to be true, is said to give false evidence.", keywords: ["perjury", "false evidence", "lying under oath"] },
  { act: "Indian Penal Code", section: "193", title: "Punishment for false evidence", content: "Whoever intentionally gives false evidence in any stage of a judicial proceeding, or fabricates false evidence for the purpose of being used in any stage of a judicial proceeding, shall be punished with imprisonment up to seven years, and shall also be liable to fine.", keywords: ["false evidence punishment", "perjury punishment"] },
  { act: "Indian Penal Code", section: "195A", title: "Threatening any person to give false evidence", content: "Whoever threatens another with any injury to his person, reputation or property or to the person or reputation of any one in whom that person is interested, with intent to cause that person to give false evidence shall be punished with imprisonment up to seven years, or with fine, or with both.", keywords: ["threatening witness", "witness intimidation"] },
  { act: "Indian Penal Code", section: "201", title: "Causing disappearance of evidence or giving false information", content: "Whoever, knowing or having reason to believe that an offence has been committed, causes any evidence of the commission of that offence to disappear, with the intention of screening the offender from legal punishment, shall be punished with imprisonment up to seven years.", keywords: ["destroying evidence", "tampering evidence", "screening offender"] },
  { act: "Indian Penal Code", section: "268", title: "Public nuisance", content: "A person is guilty of a public nuisance who does any act or is guilty of an illegal omission which causes any common injury, danger or annoyance to the public or to the people in general who dwell or occupy property in the vicinity.", keywords: ["public nuisance", "nuisance", "public disturbance"] },
  { act: "Indian Penal Code", section: "279", title: "Rash driving or riding on a public way", content: "Whoever drives any vehicle, or rides, on any public way in a manner so rash or negligent as to endanger human life, or to be likely to cause hurt or injury to any other person, shall be punished with imprisonment up to six months, or with fine up to one thousand rupees, or with both.", keywords: ["rash driving", "negligent driving", "road accident", "traffic offence"] },
  { act: "Indian Penal Code", section: "292", title: "Sale of obscene material", content: "Whoever sells, lets to hire, distributes, publicly exhibits or in any manner puts into circulation, or for purposes of sale, hire, distribution, public exhibition or circulation, makes, produces or has in his possession any obscene book, pamphlet, paper, drawing, painting, representation or figure or any other obscene object whatsoever, shall be punished with imprisonment up to two years and fine up to two thousand rupees.", keywords: ["obscene material", "pornography", "obscenity"] },
  { act: "Indian Penal Code", section: "295A", title: "Deliberate and malicious acts intended to outrage religious feelings", content: "Whoever, with deliberate and malicious intention of outraging the religious feelings of any class of citizens of India, by words, either spoken or written, or by signs or by visible representations or otherwise, insults or attempts to insult the religion or the religious beliefs of that class, shall be punished with imprisonment up to three years, or with fine, or with both.", keywords: ["blasphemy", "religious insult", "hurting religious sentiments"] },
  { act: "Indian Penal Code", section: "299", title: "Culpable homicide", content: "Whoever causes death by doing an act with the intention of causing death, or with the intention of causing such bodily injury as is likely to cause death, or with the knowledge that he is likely by such act to cause death, commits the offence of culpable homicide.", keywords: ["culpable homicide", "causing death", "homicide"] },
  { act: "Indian Penal Code", section: "300", title: "Murder", content: "Culpable homicide is murder if the act by which the death is caused is done with the intention of causing death, or if it is done with the intention of causing such bodily injury as the offender knows to be likely to cause the death of the person, or if it is done with the intention of causing bodily injury to any person and the bodily injury intended to be inflicted is sufficient in the ordinary course of nature to cause death.", keywords: ["murder", "homicide", "killing"] },
  { act: "Indian Penal Code", section: "302", title: "Punishment for murder", content: "Whoever commits murder shall be punished with death, or imprisonment for life, and shall also be liable to fine.", keywords: ["murder punishment", "death penalty", "life imprisonment"] },
  { act: "Indian Penal Code", section: "304A", title: "Causing death by negligence", content: "Whoever causes the death of any person by doing any rash or negligent act not amounting to culpable homicide shall be punished with imprisonment up to two years, or with fine, or with both.", keywords: ["death by negligence", "rash act", "negligent death"] },
  { act: "Indian Penal Code", section: "304B", title: "Dowry death", content: "Where the death of a woman is caused by burns or bodily injury or occurs under abnormal circumstances within seven years of marriage and she was subjected to cruelty or harassment by husband or relatives in connection with demand for dowry, such death shall be called dowry death. Punishment is imprisonment not less than seven years extending to life imprisonment.", keywords: ["dowry death", "bride burning", "dowry murder"] },
  { act: "Indian Penal Code", section: "306", title: "Abetment of suicide", content: "If any person commits suicide, whoever abets the commission of such suicide shall be punished with imprisonment up to ten years, and shall also be liable to fine.", keywords: ["abetment suicide", "suicide", "driving to suicide"] },
  { act: "Indian Penal Code", section: "307", title: "Attempt to murder", content: "Whoever does any act with such intention or knowledge and under such circumstances that if he by that act caused death he would be guilty of murder, shall be punished with imprisonment up to ten years, and shall also be liable to fine, and if hurt is caused, shall be liable to imprisonment for life.", keywords: ["attempt to murder", "attempted murder", "murder attempt"] },
  { act: "Indian Penal Code", section: "323", title: "Voluntarily causing hurt", content: "Whoever voluntarily causes hurt shall be punished with imprisonment up to one year, or with fine up to one thousand rupees, or with both.", keywords: ["hurt", "assault", "beating"] },
  { act: "Indian Penal Code", section: "324", title: "Voluntarily causing hurt by dangerous weapons", content: "Whoever voluntarily causes hurt by means of any instrument for shooting, stabbing or cutting, or any instrument which used as a weapon of offence is likely to cause death, shall be punished with imprisonment up to three years, or with fine, or with both.", keywords: ["dangerous weapon", "stabbing", "weapon assault"] },
  { act: "Indian Penal Code", section: "326", title: "Voluntarily causing grievous hurt by dangerous weapons", content: "Whoever voluntarily causes grievous hurt by means of any instrument for shooting, stabbing or cutting, or by means of fire or any heated substance, or by means of any poison or corrosive substance, shall be punished with imprisonment for life or up to ten years, and fine.", keywords: ["grievous hurt", "acid attack", "serious injury"] },
  { act: "Indian Penal Code", section: "326A", title: "Voluntarily causing grievous hurt by use of acid", content: "Whoever causes permanent or partial damage or deformity to, or burns or maims or disfigures or disables any part or parts of the body of a person or causes grievous hurt by throwing acid on or by administering acid to that person, shall be punished with imprisonment not less than ten years but which may extend to imprisonment for life, and with fine.", keywords: ["acid attack", "acid throwing", "disfigurement"] },
  { act: "Indian Penal Code", section: "354", title: "Assault on woman with intent to outrage modesty", content: "Whoever assaults or uses criminal force to any woman, intending to outrage or knowing it to be likely that he will thereby outrage her modesty, shall be punished with imprisonment not less than one year but which may extend to five years and fine.", keywords: ["molestation", "modesty", "assault on woman"] },
  { act: "Indian Penal Code", section: "354A", title: "Sexual harassment", content: "Physical contact and advances involving unwelcome and explicit sexual overtures, demand or request for sexual favours, showing pornography against will of a woman, or making sexually coloured remarks shall constitute sexual harassment. Punishment up to three years imprisonment and fine.", keywords: ["sexual harassment", "workplace harassment"] },
  { act: "Indian Penal Code", section: "354B", title: "Assault or use of criminal force to woman with intent to disrobe", content: "Any man who assaults or uses criminal force to any woman or abets such act with the intention of disrobing or compelling her to be naked, shall be punished with imprisonment not less than three years but which may extend to seven years, and with fine.", keywords: ["disrobing", "forced nudity", "assault woman"] },
  { act: "Indian Penal Code", section: "354D", title: "Stalking", content: "Any man who follows a woman and contacts or attempts to contact such woman to foster personal interaction repeatedly despite clear indication of disinterest, or monitors use of internet or electronic communication by a woman, commits stalking. Punishment up to three years imprisonment and fine.", keywords: ["stalking", "cyberstalking", "following"] },
  { act: "Indian Penal Code", section: "363", title: "Punishment for kidnapping", content: "Whoever kidnaps any person from India or from lawful guardianship shall be punished with imprisonment up to seven years, and shall also be liable to fine.", keywords: ["kidnapping", "abduction"] },
  { act: "Indian Penal Code", section: "366", title: "Kidnapping or abducting woman to compel marriage", content: "Whoever kidnaps or abducts any woman with intent that she may be compelled, or knowing it to be likely that she will be compelled, to marry any person against her will, or in order that she may be forced or seduced to illicit intercourse, shall be punished with imprisonment up to ten years, and shall also be liable to fine.", keywords: ["forced marriage", "kidnapping woman", "abduction for marriage"] },
  { act: "Indian Penal Code", section: "375", title: "Rape", content: "A man is said to commit rape if he penetrates or does sexual acts with a woman under circumstances including against her will, without her consent, with consent obtained by threat or fear, when she is unable to communicate consent, or when she is under 18 years of age.", keywords: ["rape", "sexual assault", "consent"] },
  { act: "Indian Penal Code", section: "376", title: "Punishment for rape", content: "Whoever commits rape shall be punished with rigorous imprisonment for not less than ten years but which may extend to imprisonment for life, and shall also be liable to fine.", keywords: ["rape punishment", "sexual assault punishment"] },
  { act: "Indian Penal Code", section: "376A", title: "Punishment for causing death or persistent vegetative state during rape", content: "Whoever commits an offence of rape and in the course of such commission inflicts an injury which causes the death of the woman or causes the woman to be in a persistent vegetative state, shall be punished with rigorous imprisonment for not less than twenty years, but which may extend to imprisonment for life or with death.", keywords: ["rape murder", "rape death"] },
  { act: "Indian Penal Code", section: "376D", title: "Gang rape", content: "Where a woman is raped by one or more persons constituting a group or acting in furtherance of a common intention, each of those persons shall be deemed to have committed the offence of rape and shall be punished with rigorous imprisonment for not less than twenty years, but which may extend to life, and with fine.", keywords: ["gang rape", "group rape"] },
  { act: "Indian Penal Code", section: "378", title: "Theft", content: "Whoever, intending to take dishonestly any moveable property out of the possession of any person without that person's consent, moves that property in order to such taking, is said to commit theft.", keywords: ["theft", "stealing", "larceny"] },
  { act: "Indian Penal Code", section: "379", title: "Punishment for theft", content: "Whoever commits theft shall be punished with imprisonment up to three years, or with fine, or with both.", keywords: ["theft punishment"] },
  { act: "Indian Penal Code", section: "380", title: "Theft in dwelling house", content: "Whoever commits theft in any building, tent or vessel used as a human dwelling or for custody of property shall be punished with imprisonment up to seven years, and fine.", keywords: ["house theft", "burglary"] },
  { act: "Indian Penal Code", section: "384", title: "Punishment for extortion", content: "Whoever commits extortion shall be punished with imprisonment up to three years, or with fine, or with both.", keywords: ["extortion", "blackmail"] },
  { act: "Indian Penal Code", section: "390", title: "Robbery", content: "In all robbery there is either theft or extortion. Theft is robbery if the offender voluntarily causes or attempts to cause death, hurt, or wrongful restraint, or fear thereof.", keywords: ["robbery", "armed robbery"] },
  { act: "Indian Penal Code", section: "395", title: "Punishment for dacoity", content: "Whoever commits dacoity shall be punished with imprisonment for life, or with rigorous imprisonment up to ten years, and fine.", keywords: ["dacoity", "gang robbery"] },
  { act: "Indian Penal Code", section: "406", title: "Criminal breach of trust", content: "Whoever commits criminal breach of trust shall be punished with imprisonment up to three years, or with fine, or with both.", keywords: ["breach of trust", "misappropriation"] },
  { act: "Indian Penal Code", section: "415", title: "Cheating", content: "Whoever, by deceiving any person, fraudulently or dishonestly induces the person so deceived to deliver any property to any person, or to consent that any person shall retain any property, is said to cheat.", keywords: ["cheating", "fraud", "deception"] },
  { act: "Indian Penal Code", section: "420", title: "Cheating and dishonestly inducing delivery of property", content: "Whoever cheats and thereby dishonestly induces the person deceived to deliver any property to any person shall be punished with imprisonment up to seven years, and fine.", keywords: ["420 fraud", "cheating", "property fraud"] },
  { act: "Indian Penal Code", section: "425", title: "Mischief", content: "Whoever with intent to cause, or knowing that he is likely to cause, wrongful loss or damage to the public or to any person, causes the destruction of any property, or any such change in any property or in the situation thereof as destroys or diminishes its value or utility, commits mischief.", keywords: ["mischief", "property damage", "vandalism"] },
  { act: "Indian Penal Code", section: "441", title: "Criminal trespass", content: "Whoever enters into or upon property in the possession of another with intent to commit an offence or to intimidate, insult or annoy any person in possession of such property, is said to commit criminal trespass.", keywords: ["trespass", "illegal entry"] },
  { act: "Indian Penal Code", section: "463", title: "Forgery", content: "Whoever makes any false document or false electronic record with intent to cause damage or injury, or to support any claim or title, or to cause any person to part with property, commits forgery.", keywords: ["forgery", "fake document"] },
  { act: "Indian Penal Code", section: "468", title: "Forgery for purpose of cheating", content: "Whoever commits forgery intending that the document forged shall be used for cheating shall be punished with imprisonment up to seven years, and fine.", keywords: ["forgery cheating", "fake documents"] },
  { act: "Indian Penal Code", section: "471", title: "Using as genuine a forged document", content: "Whoever fraudulently or dishonestly uses as genuine any document or electronic record which he knows or has reason to believe to be a forged document or electronic record, shall be punished in the same manner as if he had forged such document.", keywords: ["using forged document", "fake document use"] },
  { act: "Indian Penal Code", section: "489A", title: "Counterfeiting currency notes", content: "Whoever counterfeits any currency note or bank note shall be punished with imprisonment for life, or imprisonment up to ten years, and fine.", keywords: ["counterfeiting", "fake currency"] },
  { act: "Indian Penal Code", section: "494", title: "Bigamy", content: "Whoever, having a husband or wife living, marries again in any case in which such marriage is void by reason of its taking place during the life of such husband or wife, shall be punished with imprisonment up to seven years, and fine.", keywords: ["bigamy", "second marriage"] },
  { act: "Indian Penal Code", section: "498A", title: "Cruelty by husband or relatives", content: "Whoever, being the husband or relative of the husband of a woman, subjects such woman to cruelty shall be punished with imprisonment up to three years and fine. Cruelty includes conduct driving woman to suicide, causing grave injury, or harassment for dowry.", keywords: ["498A", "dowry harassment", "domestic violence", "cruelty"] },
  { act: "Indian Penal Code", section: "499", title: "Defamation", content: "Whoever by words spoken or written, or by signs or visible representations, makes or publishes any imputation concerning any person intending to harm the reputation of such person, is said to defame that person.", keywords: ["defamation", "slander", "libel"] },
  { act: "Indian Penal Code", section: "500", title: "Punishment for defamation", content: "Whoever defames another shall be punished with simple imprisonment up to two years, or with fine, or with both.", keywords: ["defamation punishment"] },
  { act: "Indian Penal Code", section: "503", title: "Criminal intimidation", content: "Whoever threatens another with any injury to his person, reputation or property with intent to cause alarm or to cause that person to do any act which he is not legally bound to do, commits criminal intimidation.", keywords: ["intimidation", "threat", "threatening"] },
  { act: "Indian Penal Code", section: "506", title: "Punishment for criminal intimidation", content: "Whoever commits criminal intimidation shall be punished with imprisonment up to two years, or fine, or both. If threat is to cause death or grievous hurt, imprisonment up to seven years.", keywords: ["criminal intimidation", "death threat"] },
  { act: "Indian Penal Code", section: "509", title: "Insulting modesty of woman", content: "Whoever intending to insult the modesty of any woman utters any word, makes any sound or gesture, or exhibits any object intending that such shall be heard or seen by such woman, shall be punished with imprisonment up to three years and fine.", keywords: ["eve teasing", "insult modesty", "harassment women"] },
  { act: "Indian Penal Code", section: "511", title: "Punishment for attempting to commit offences", content: "Whoever attempts to commit an offence punishable by this Code with imprisonment for life or imprisonment, and in such attempt does any act towards the commission of the offence, shall be punished with imprisonment up to one-half of the longest term of imprisonment provided for that offence.", keywords: ["attempt", "criminal attempt"] },
  // ===== INFORMATION TECHNOLOGY ACT 2000 - 40 sections =====
  { act: "Information Technology Act 2000", section: "43", title: "Penalty for damage to computer system", content: "If any person without permission of the owner accesses or secures access to a computer, downloads or copies data, introduces any computer virus, damages or causes damage to any computer system, disrupts or causes disruption of any computer, denies or causes denial of access to any person, charges the services availed of by a person to the account of another person, he shall be liable to pay damages by way of compensation to the person so affected.", keywords: ["hacking", "unauthorized access", "computer damage", "virus"] },
  { act: "Information Technology Act 2000", section: "43A", title: "Compensation for failure to protect data", content: "Where a body corporate, possessing, dealing or handling any sensitive personal data or information in a computer resource which it owns, controls or operates, is negligent in implementing and maintaining reasonable security practices and procedures and thereby causes wrongful loss or wrongful gain to any person, such body corporate shall be liable to pay damages by way of compensation to the person so affected.", keywords: ["data protection", "data breach", "personal data", "compensation"] },
  { act: "Information Technology Act 2000", section: "65", title: "Tampering with computer source documents", content: "Whoever knowingly or intentionally conceals, destroys or alters or intentionally or knowingly causes another to conceal, destroy, or alter any computer source code used for a computer, computer programme, computer system or computer network, when the computer source code is required to be kept or maintained by law, shall be punishable with imprisonment up to three years, or with fine up to two lakh rupees, or with both.", keywords: ["source code tampering", "computer source code", "code destruction"] },
  { act: "Information Technology Act 2000", section: "66", title: "Computer related offences", content: "If any person, dishonestly or fraudulently, does any act referred to in section 43, he shall be punishable with imprisonment for a term which may extend to three years or with fine which may extend to five lakh rupees or with both.", keywords: ["computer crime", "hacking", "cyber crime", "unauthorized access"] },
  { act: "Information Technology Act 2000", section: "66A", title: "Sending offensive messages (Struck down)", content: "Section 66A which dealt with punishment for sending offensive messages through communication service was struck down by the Supreme Court of India in Shreya Singhal v. Union of India (2015) as unconstitutional for violating Article 19(1)(a) of the Constitution.", keywords: ["offensive messages", "66A", "free speech", "struck down"] },
  { act: "Information Technology Act 2000", section: "66B", title: "Punishment for dishonestly receiving stolen computer resource", content: "Whoever dishonestly receives or retains any stolen computer resource or communication device knowing or having reason to believe the same to be stolen shall be punished with imprisonment up to three years or fine up to one lakh rupees or both.", keywords: ["stolen computer", "receiving stolen property", "stolen device"] },
  { act: "Information Technology Act 2000", section: "66C", title: "Punishment for identity theft", content: "Whoever, fraudulently or dishonestly makes use of the electronic signature, password or any other unique identification feature of any other person, shall be punished with imprisonment up to three years and fine up to one lakh rupees.", keywords: ["identity theft", "password theft", "electronic signature fraud"] },
  { act: "Information Technology Act 2000", section: "66D", title: "Punishment for cheating by personation using computer resource", content: "Whoever, by means of any communication device or computer resource cheats by personation, shall be punished with imprisonment up to three years and fine up to one lakh rupees.", keywords: ["online cheating", "impersonation", "cyber fraud", "phishing"] },
  { act: "Information Technology Act 2000", section: "66E", title: "Punishment for violation of privacy", content: "Whoever, intentionally or knowingly captures, publishes or transmits the image of a private area of any person without his or her consent, under circumstances violating the privacy of that person, shall be punished with imprisonment up to three years or fine not exceeding two lakh rupees, or both.", keywords: ["privacy violation", "voyeurism", "intimate images", "privacy"] },
  { act: "Information Technology Act 2000", section: "66F", title: "Punishment for cyber terrorism", content: "Whoever with intent to threaten the unity, integrity, security or sovereignty of India or to strike terror in the people by denying or causing denial of access to any person authorized to access computer resource, or attempting to penetrate or access a computer resource without authorization, or introducing any computer contaminant, and by means of such conduct causes or is likely to cause death or injuries to persons or damage to or destruction of property, shall be punishable with imprisonment which may extend to imprisonment for life.", keywords: ["cyber terrorism", "terrorism", "national security", "cyber attack"] },
  { act: "Information Technology Act 2000", section: "67", title: "Punishment for publishing obscene material in electronic form", content: "Whoever publishes or transmits or causes to be published or transmitted in the electronic form, any material which is lascivious or appeals to the prurient interest shall be punished on first conviction with imprisonment up to three years and fine up to five lakh rupees and on second conviction with imprisonment up to five years and fine up to ten lakh rupees.", keywords: ["obscene content", "pornography online", "electronic obscenity"] },
  { act: "Information Technology Act 2000", section: "67A", title: "Punishment for publishing sexually explicit material", content: "Whoever publishes or transmits or causes to be published or transmitted in the electronic form any material which contains sexually explicit act or conduct shall be punished on first conviction with imprisonment up to five years and fine up to ten lakh rupees.", keywords: ["sexually explicit", "adult content", "electronic pornography"] },
  { act: "Information Technology Act 2000", section: "67B", title: "Punishment for publishing child pornography", content: "Whoever publishes or transmits or causes to be published or transmitted material in electronic form which depicts children engaged in sexually explicit act or conduct, or creates, collects, seeks, browses, downloads, advertises, promotes, exchanges or distributes material depicting children in obscene or indecent manner, shall be punished on first conviction with imprisonment up to five years and fine up to ten lakh rupees.", keywords: ["child pornography", "CSAM", "child exploitation"] },
  { act: "Information Technology Act 2000", section: "69", title: "Power to issue directions for interception or monitoring", content: "Where the Central Government or a State Government is satisfied that it is necessary or expedient to do so in the interest of the sovereignty or integrity of India, defence of India, security of the State, friendly relations with foreign States or public order, it may direct any agency of the appropriate Government to intercept, monitor or decrypt any information generated, transmitted, received or stored in any computer resource.", keywords: ["surveillance", "interception", "monitoring", "government power"] },
  { act: "Information Technology Act 2000", section: "69A", title: "Power to issue directions for blocking public access", content: "Where the Central Government is satisfied that it is necessary or expedient to do so in the interest of sovereignty and integrity of India, defence of India, security of the State, friendly relations with foreign States or public order, it may direct any agency of the Government or intermediary to block for access by the public any information generated, transmitted, received, stored or hosted in any computer resource.", keywords: ["website blocking", "content blocking", "internet censorship"] },
  { act: "Information Technology Act 2000", section: "70", title: "Protected system", content: "The appropriate Government may, by notification in the Official Gazette, declare any computer resource which directly or indirectly affects the facility of Critical Information Infrastructure, to be a protected system. Any person who secures access or attempts to secure access to a protected system in contravention shall be punished with imprisonment up to ten years and fine.", keywords: ["protected system", "critical infrastructure", "government systems"] },
  { act: "Information Technology Act 2000", section: "72", title: "Breach of confidentiality and privacy", content: "Save as otherwise provided in this Act or any other law for the time being in force, any person who, in pursuance of any of the powers conferred under this Act, has secured access to any electronic record, book, register, correspondence, information, document or other material without the consent of the person concerned discloses such material to any other person shall be punished with imprisonment up to two years, or with fine up to one lakh rupees, or with both.", keywords: ["confidentiality breach", "privacy breach", "unauthorized disclosure"] },
  { act: "Information Technology Act 2000", section: "72A", title: "Punishment for disclosure of information in breach of lawful contract", content: "Any person including an intermediary who, while providing services under the terms of lawful contract, has secured access to any material containing personal information about another person, with the intent to cause or knowing that he is likely to cause wrongful loss or wrongful gain discloses, without the consent of the person concerned, such material to any other person, shall be punished with imprisonment up to three years, or with fine up to five lakh rupees, or with both.", keywords: ["data breach", "contract breach", "personal information disclosure"] },
  { act: "Information Technology Act 2000", section: "79", title: "Exemption from liability of intermediary", content: "An intermediary shall not be liable for any third party information, data, or communication link made available or hosted by him if he merely provides access to a communication system, does not initiate the transmission, select the receiver, or select or modify the information. However, this exemption shall not apply if the intermediary has conspired or abetted or aided or induced the commission of the unlawful act, or upon receiving actual knowledge fails to expeditiously remove or disable access to that material.", keywords: ["intermediary liability", "safe harbour", "platform liability", "social media liability"] },
  // ===== INDIAN CONTRACT ACT 1872 - 40 sections =====
  { act: "Indian Contract Act 1872", section: "2", title: "Definitions", content: "When one person signifies to another his willingness to do or to abstain from doing anything, with a view to obtaining the assent of that other to such act or abstinence, he is said to make a proposal. When the person to whom the proposal is made signifies his assent thereto, the proposal is said to be accepted. A proposal when accepted becomes a promise. Every promise and every set of promises forming the consideration for each other is an agreement. An agreement enforceable by law is a contract.", keywords: ["contract", "proposal", "acceptance", "agreement", "promise"] },
  { act: "Indian Contract Act 1872", section: "10", title: "What agreements are contracts", content: "All agreements are contracts if they are made by the free consent of parties competent to contract, for a lawful consideration and with a lawful object, and are not hereby expressly declared to be void.", keywords: ["valid contract", "free consent", "lawful consideration"] },
  { act: "Indian Contract Act 1872", section: "11", title: "Who are competent to contract", content: "Every person is competent to contract who is of the age of majority according to the law to which he is subject, and who is of sound mind, and is not disqualified from contracting by any law to which he is subject.", keywords: ["competent to contract", "minor", "sound mind", "capacity"] },
  { act: "Indian Contract Act 1872", section: "13", title: "Consent defined", content: "Two or more persons are said to consent when they agree upon the same thing in the same sense.", keywords: ["consent", "agreement", "meeting of minds"] },
  { act: "Indian Contract Act 1872", section: "14", title: "Free consent", content: "Consent is said to be free when it is not caused by coercion, undue influence, fraud, misrepresentation, or mistake.", keywords: ["free consent", "coercion", "undue influence", "fraud", "misrepresentation"] },
  { act: "Indian Contract Act 1872", section: "15", title: "Coercion", content: "Coercion is the committing, or threatening to commit, any act forbidden by the Indian Penal Code, or the unlawful detaining, or threatening to detain, any property, to the prejudice of any person whatever, with the intention of causing any person to enter into an agreement.", keywords: ["coercion", "threat", "forced agreement"] },
  { act: "Indian Contract Act 1872", section: "16", title: "Undue influence", content: "A contract is said to be induced by undue influence where the relations subsisting between the parties are such that one of the parties is in a position to dominate the will of the other and uses that position to obtain an unfair advantage over the other.", keywords: ["undue influence", "dominant position", "unfair advantage"] },
  { act: "Indian Contract Act 1872", section: "17", title: "Fraud", content: "Fraud means and includes any of the following acts committed by a party to a contract with intent to deceive another party: the suggestion as a fact of that which is not true by one who does not believe it to be true, the active concealment of a fact by one having knowledge or belief of the fact, a promise made without any intention of performing it, any other act fitted to deceive, any such act or omission as the law specially declares to be fraudulent.", keywords: ["fraud", "deception", "contract fraud", "misrepresentation"] },
  { act: "Indian Contract Act 1872", section: "23", title: "What considerations and objects are lawful", content: "The consideration or object of an agreement is lawful unless it is forbidden by law, or is of such nature that if permitted it would defeat the provisions of any law, or is fraudulent, or involves or implies injury to the person or property of another, or the Court regards it as immoral or opposed to public policy.", keywords: ["lawful consideration", "illegal agreement", "public policy"] },
  { act: "Indian Contract Act 1872", section: "25", title: "Agreement without consideration void", content: "An agreement made without consideration is void, unless it is expressed in writing and registered, or is a promise to compensate for something done, or is a promise to pay a debt barred by limitation law.", keywords: ["consideration", "void agreement", "no consideration"] },
  { act: "Indian Contract Act 1872", section: "27", title: "Agreement in restraint of trade void", content: "Every agreement by which any one is restrained from exercising a lawful profession, trade or business of any kind, is to that extent void. Exception: One who sells the goodwill of a business may agree with the buyer to refrain from carrying on a similar business within specified local limits.", keywords: ["restraint of trade", "non-compete", "business restriction"] },
  { act: "Indian Contract Act 1872", section: "28", title: "Agreements in restraint of legal proceedings void", content: "Every agreement by which any party thereto is restricted absolutely from enforcing his rights under or in respect of any contract, by the usual legal proceedings in the ordinary tribunals, is void to that extent.", keywords: ["restraint of legal proceedings", "right to sue"] },
  { act: "Indian Contract Act 1872", section: "29", title: "Agreements void for uncertainty", content: "Agreements the meaning of which is not certain, or capable of being made certain, are void.", keywords: ["uncertain agreement", "vague contract", "void for uncertainty"] },
  { act: "Indian Contract Act 1872", section: "30", title: "Agreements by way of wager void", content: "Agreements by way of wager are void; and no suit shall be brought for recovering anything alleged to be won on any wager, or entrusted to any person to abide the result of any game or other uncertain event on which any wager is made.", keywords: ["wager", "betting", "gambling agreement"] },
  { act: "Indian Contract Act 1872", section: "39", title: "Effect of refusal to perform promise wholly", content: "When a party to a contract has refused to perform, or disabled himself from performing, his promise in its entirety, the promisee may put an end to the contract, unless he has signified, by words or conduct, his acquiescence in its continuance.", keywords: ["breach of contract", "refusal to perform", "contract termination"] },
  { act: "Indian Contract Act 1872", section: "56", title: "Agreement to do impossible act", content: "An agreement to do an act impossible in itself is void. A contract to do an act which, after the contract is made, becomes impossible, or by reason of some event which the promisor could not prevent, unlawful, becomes void when the act becomes impossible or unlawful.", keywords: ["impossible act", "frustration", "void contract", "impossibility"] },
  { act: "Indian Contract Act 1872", section: "73", title: "Compensation for breach of contract", content: "When a contract has been broken, the party who suffers by such breach is entitled to receive, as compensation for any loss or damage caused to him thereby, such compensation as naturally arose in the usual course of things from such breach, or which the parties knew when they made the contract to be likely to result from the breach of it.", keywords: ["breach compensation", "damages", "contract damages"] },
  { act: "Indian Contract Act 1872", section: "74", title: "Compensation for breach where penalty stipulated", content: "When a contract has been broken, if a sum is named in the contract as the amount to be paid in case of such breach, or if the contract contains any other stipulation by way of penalty, the party complaining of the breach is entitled to receive from the party who has broken the contract, reasonable compensation not exceeding the amount so named.", keywords: ["penalty clause", "liquidated damages", "breach penalty"] },
  { act: "Indian Contract Act 1872", section: "124", title: "Contract of indemnity", content: "A contract by which one party promises to save the other from loss caused to him by the conduct of the promisor himself, or by the conduct of any other person, is called a contract of indemnity.", keywords: ["indemnity", "indemnification", "save from loss"] },
  { act: "Indian Contract Act 1872", section: "126", title: "Contract of guarantee", content: "A contract of guarantee is a contract to perform the promise, or discharge the liability, of a third person in case of his default. The person who gives the guarantee is called the surety, the person in respect of whose default the guarantee is given is called the principal debtor, and the person to whom the guarantee is given is called the creditor.", keywords: ["guarantee", "surety", "guarantor", "principal debtor"] },
  { act: "Indian Contract Act 1872", section: "148", title: "Bailment defined", content: "A bailment is the delivery of goods by one person to another for some purpose, upon a contract that they shall, when the purpose is accomplished, be returned or otherwise disposed of according to the directions of the person delivering them.", keywords: ["bailment", "delivery of goods", "custody"] },
  { act: "Indian Contract Act 1872", section: "172", title: "Pledge defined", content: "The bailment of goods as security for payment of a debt or performance of a promise is called pledge. The bailor is in this case called the pawnor and the bailee is called the pawnee.", keywords: ["pledge", "pawn", "security", "collateral"] },
  { act: "Indian Contract Act 1872", section: "182", title: "Agent and principal", content: "An agent is a person employed to do any act for another, or to represent another in dealings with third persons. The person for whom such act is done, or who is so represented, is called the principal.", keywords: ["agent", "principal", "agency", "representation"] },
  // ===== CONSUMER PROTECTION ACT 2019 - 30 sections =====
  { act: "Consumer Protection Act 2019", section: "2(7)", title: "Consumer defined", content: "Consumer means any person who buys any goods for a consideration which has been paid or promised or partly paid and partly promised, or under any system of deferred payment, and includes any user of such goods other than the person who buys such goods. It also includes any person who hires or avails of any service for a consideration.", keywords: ["consumer", "buyer", "customer", "consumer definition"] },
  { act: "Consumer Protection Act 2019", section: "2(9)", title: "Defect defined", content: "Defect means any fault, imperfection or shortcoming in the quality, quantity, potency, purity or standard which is required to be maintained by or under any law for the time being in force or under any contract, express or implied, or as is claimed by the trader in any manner whatsoever in relation to any goods or product.", keywords: ["defect", "product defect", "quality issue", "faulty product"] },
  { act: "Consumer Protection Act 2019", section: "2(11)", title: "Deficiency defined", content: "Deficiency means any fault, imperfection, shortcoming or inadequacy in the quality, nature and manner of performance which is required to be maintained by or under any law for the time being in force or has been undertaken to be performed by a person in pursuance of a contract or otherwise in relation to any service.", keywords: ["deficiency", "service deficiency", "poor service", "inadequate service"] },
  { act: "Consumer Protection Act 2019", section: "2(28)", title: "Misleading advertisement", content: "Misleading advertisement means any advertisement which falsely describes a product or service, gives a false guarantee or is likely to mislead the consumers as to the nature, substance, quantity or quality of such product or service, conveys an express or implied representation which would constitute an unfair trade practice, or deliberately conceals important information.", keywords: ["misleading advertisement", "false advertising", "deceptive marketing"] },
  { act: "Consumer Protection Act 2019", section: "2(42)", title: "Product liability", content: "Product liability means the responsibility of a product manufacturer or product seller, of any product or service, to compensate for any harm caused to a consumer by such defective product manufactured or sold or by deficiency in services relating thereto.", keywords: ["product liability", "manufacturer liability", "defective product"] },
  { act: "Consumer Protection Act 2019", section: "2(47)", title: "Unfair trade practice", content: "Unfair trade practice means a trade practice which, for the purpose of promoting the sale, use or supply of any goods or for the provision of any service, adopts any unfair method or unfair or deceptive practice including making any statement, whether orally or in writing or by visible representation which falsely represents that the goods are of a particular standard, quality, quantity, grade, composition, style or model.", keywords: ["unfair trade practice", "deceptive practice", "false representation"] },
  { act: "Consumer Protection Act 2019", section: "18", title: "District Commission jurisdiction", content: "The District Commission shall have jurisdiction to entertain complaints where the value of the goods or services paid as consideration does not exceed one crore rupees.", keywords: ["district commission", "consumer court", "jurisdiction", "complaint"] },
  { act: "Consumer Protection Act 2019", section: "34", title: "Filing of complaint", content: "A complaint in relation to any goods sold or delivered or agreed to be sold or delivered or any service provided or agreed to be provided may be filed with the District Commission by the consumer to whom such goods are sold or delivered or agreed to be sold or delivered or such service provided or agreed to be provided.", keywords: ["consumer complaint", "filing complaint", "consumer court"] },
  { act: "Consumer Protection Act 2019", section: "35", title: "Complaint filing procedure", content: "Every complaint shall be filed within two years from the date on which the cause of action has arisen. A complaint shall contain the name, description and address of the complainant and opposite party, the facts relating to complaint, and the relief which the complainant claims.", keywords: ["complaint procedure", "limitation period", "consumer complaint filing"] },
  { act: "Consumer Protection Act 2019", section: "38", title: "Remedies available to consumer", content: "If the District Commission is satisfied that the goods complained against suffer from any defect or the services suffer from any deficiency, it shall issue an order to the opposite party directing removal of defect, replacement of goods, return of price, payment of compensation for any loss or injury suffered, discontinue unfair trade practice, or provide adequate costs to parties.", keywords: ["consumer remedies", "refund", "replacement", "compensation"] },
  { act: "Consumer Protection Act 2019", section: "39", title: "Appeal from District Commission", content: "Any person aggrieved by an order made by the District Commission may prefer an appeal against such order to the State Commission on the grounds of facts or law within a period of forty-five days from the date of the order.", keywords: ["consumer appeal", "state commission", "appeal period"] },
  { act: "Consumer Protection Act 2019", section: "47", title: "State Commission jurisdiction", content: "The State Commission shall have jurisdiction to entertain complaints where the value of the goods or services paid as consideration exceeds one crore rupees but does not exceed ten crore rupees, and to entertain appeals against the orders of any District Commission within the State.", keywords: ["state commission", "jurisdiction", "consumer appeal"] },
  { act: "Consumer Protection Act 2019", section: "58", title: "National Commission jurisdiction", content: "The National Commission shall have jurisdiction to entertain complaints where the value of the goods or services paid as consideration exceeds ten crore rupees, and to entertain appeals against the orders of any State Commission.", keywords: ["national commission", "high value complaint", "consumer appeal"] },
  { act: "Consumer Protection Act 2019", section: "82", title: "Product liability action", content: "A product liability action may be brought by a complainant against a product manufacturer or a product service provider or a product seller for any harm caused to him on account of a defective product.", keywords: ["product liability action", "defective product claim", "manufacturer responsibility"] },
  { act: "Consumer Protection Act 2019", section: "84", title: "Liability of product manufacturer", content: "A product manufacturer shall be liable in a product liability action if the product contains a manufacturing defect, is defective in design, there is a deviation from manufacturing specifications, the product does not conform to the express warranty, or the product fails to contain adequate instructions of correct usage to prevent any harm.", keywords: ["manufacturer liability", "manufacturing defect", "design defect", "warranty"] },
  { act: "Consumer Protection Act 2019", section: "89", title: "Central Consumer Protection Authority", content: "The Central Government shall establish a body to be known as the Central Consumer Protection Authority to regulate matters relating to violation of rights of consumers, unfair trade practices and false or misleading advertisements which are prejudicial to the interests of public and consumers.", keywords: ["CCPA", "consumer authority", "consumer protection authority"] },
  // ===== RIGHT TO INFORMATION ACT 2005 - 20 sections =====
  { act: "Right to Information Act 2005", section: "2(f)", title: "Information defined", content: "Information means any material in any form, including records, documents, memos, e-mails, opinions, advices, press releases, circulars, orders, logbooks, contracts, reports, papers, samples, models, data material held in any electronic form and information relating to any private body which can be accessed by a public authority under any other law for the time being in force.", keywords: ["information", "RTI", "public information"] },
  { act: "Right to Information Act 2005", section: "3", title: "Right to information", content: "Subject to the provisions of this Act, all citizens shall have the right to information.", keywords: ["right to information", "RTI right", "citizen right"] },
  { act: "Right to Information Act 2005", section: "4", title: "Obligations of public authorities", content: "Every public authority shall maintain all its records duly catalogued and indexed in a manner and form which facilitates the right to information under this Act and ensure that all records that are appropriate to be computerised are, within a reasonable time and subject to availability of resources, computerised and connected through a network all over the country on different systems.", keywords: ["public authority obligation", "record maintenance", "transparency"] },
  { act: "Right to Information Act 2005", section: "6", title: "Request for obtaining information", content: "A person who desires to obtain any information under this Act shall make a request in writing or through electronic means in English or Hindi or in the official language of the area in which the application is being made, accompanied by the prescribed fee, to the Central Public Information Officer or State Public Information Officer of the concerned public authority.", keywords: ["RTI application", "information request", "RTI filing"] },
  { act: "Right to Information Act 2005", section: "7", title: "Disposal of request", content: "The Central Public Information Officer or State Public Information Officer on receipt of a request shall as expeditiously as possible, and in any case within thirty days of the receipt of the request, either provide the information on payment of such fee as may be prescribed or reject the request for any of the reasons specified in sections 8 and 9.", keywords: ["RTI response", "30 days", "information disposal"] },
  { act: "Right to Information Act 2005", section: "8", title: "Exemption from disclosure of information", content: "There shall be no obligation to give any citizen information which would prejudicially affect the sovereignty and integrity of India, the security, strategic, scientific or economic interests of the State, information which has been expressly forbidden to be published by any court of law or tribunal, information the disclosure of which would cause a breach of privilege of Parliament or State Legislature, commercial confidence or trade secrets, information received in confidence from foreign Government, or information which would endanger the life or physical safety of any person.", keywords: ["RTI exemption", "classified information", "national security", "trade secret"] },
  { act: "Right to Information Act 2005", section: "18", title: "Powers and functions of Information Commissions", content: "The Central Information Commission or State Information Commission shall receive and inquire into a complaint from any person who has been unable to submit a request to a Central or State Public Information Officer, who has been refused access to any information requested, who has not been given a response to a request within the time limit specified, or who has been required to pay an amount of fee which he considers unreasonable.", keywords: ["information commission", "RTI complaint", "appeal"] },
  { act: "Right to Information Act 2005", section: "19", title: "Appeal", content: "Any person who does not receive a decision within the time specified or is aggrieved by a decision of the Central or State Public Information Officer may within thirty days from the expiry of such period or from the receipt of such a decision prefer an appeal to such officer who is senior in rank to the Central or State Public Information Officer. A second appeal shall lie within ninety days to the Central or State Information Commission.", keywords: ["RTI appeal", "first appeal", "second appeal", "information commission"] },
  { act: "Right to Information Act 2005", section: "20", title: "Penalties", content: "Where the Central or State Information Commission is of the opinion that the Central or State Public Information Officer has without any reasonable cause refused to receive an application or has not furnished information within the time specified or malafidely denied the request or knowingly given incorrect, incomplete or misleading information, it shall impose a penalty of two hundred and fifty rupees each day till the application is received or information is furnished, so however the total amount of such penalty shall not exceed twenty-five thousand rupees.", keywords: ["RTI penalty", "information officer penalty", "RTI fine"] },
  // ===== MOTOR VEHICLES ACT 1988 - 25 sections =====
  { act: "Motor Vehicles Act 1988", section: "3", title: "Necessity for driving licence", content: "No person shall drive a motor vehicle in any public place unless he holds an effective driving licence issued to him authorizing him to drive the vehicle.", keywords: ["driving licence", "licence requirement", "driving without licence"] },
  { act: "Motor Vehicles Act 1988", section: "4", title: "Age limit in connection with driving of motor vehicles", content: "No person under the age of eighteen years shall drive a motor vehicle in any public place. No person under the age of twenty years shall drive a transport vehicle in any public place. A person may drive a motor cycle with engine capacity not exceeding 50cc at the age of sixteen years.", keywords: ["driving age", "minimum age", "underage driving"] },
  { act: "Motor Vehicles Act 1988", section: "39", title: "Necessity for insurance against third party risk", content: "No person shall use, except as a passenger, or cause or allow any other person to use, a motor vehicle in a public place, unless there is in force in relation to the use of the vehicle by that person or that other person, as the case may be, a policy of insurance complying with the requirements of this Chapter.", keywords: ["motor insurance", "third party insurance", "vehicle insurance"] },
  { act: "Motor Vehicles Act 1988", section: "112", title: "Limits of speed", content: "No person shall drive a motor vehicle in any public place at a speed exceeding the maximum speed or below the minimum speed fixed for the area or for the type of vehicle by the State Government.", keywords: ["speed limit", "overspeeding", "traffic speed"] },
  { act: "Motor Vehicles Act 1988", section: "113", title: "Limits of weight and limitation on use", content: "No person shall drive or cause or allow to be driven in any public place any motor vehicle or trailer which is loaded in excess of the laden weight as specified by the manufacturer.", keywords: ["overloading", "weight limit", "vehicle weight"] },
  { act: "Motor Vehicles Act 1988", section: "128", title: "Safety measures for drivers and pillion riders", content: "Every driver of a two-wheeled motor vehicle and every person riding on such vehicle shall while in a public place wear protective headgear conforming to the standards of Bureau of Indian Standards.", keywords: ["helmet", "headgear", "two wheeler safety", "pillion rider"] },
  { act: "Motor Vehicles Act 1988", section: "129", title: "Wearing of seat belts", content: "No person driving or riding in the front seat of a motor vehicle shall allow himself to be driven or ride without wearing a seat belt.", keywords: ["seat belt", "safety belt", "car safety"] },
  { act: "Motor Vehicles Act 1988", section: "130", title: "Duty to produce licence and certificate of insurance", content: "The driver of a motor vehicle in any public place shall, on being so required by any police officer in uniform, produce his driving licence and certificate of insurance for examination.", keywords: ["produce licence", "police check", "document verification"] },
  { act: "Motor Vehicles Act 1988", section: "134", title: "Duty of driver in case of accident", content: "When any person is injured or any property of a third party is damaged as a result of an accident involving a motor vehicle, the driver of the vehicle shall take all reasonable steps to secure medical attention for the injured person and shall report the circumstances of the occurrence to the nearest police station as soon as possible and in any case within twenty-four hours of the occurrence.", keywords: ["accident duty", "hit and run", "accident reporting", "medical help"] },
  { act: "Motor Vehicles Act 1988", section: "140", title: "Liability to pay compensation in certain cases on the principle of no fault", content: "Where death or permanent disablement of any person has resulted from an accident arising out of the use of a motor vehicle, the owner of the vehicle shall be liable to pay compensation of not less than fifty thousand rupees in case of death and twenty-five thousand rupees in case of permanent disablement.", keywords: ["no fault liability", "accident compensation", "motor accident claim"] },
  { act: "Motor Vehicles Act 1988", section: "146", title: "Requirements of policies and limits of liability", content: "The policy of insurance must be a policy which insures the person or classes of persons specified in the policy to the extent specified against any liability which may be incurred by him in respect of the death of or bodily injury to any person caused by or arising out of the use of the vehicle in a public place.", keywords: ["insurance policy", "liability coverage", "motor insurance requirements"] },
  { act: "Motor Vehicles Act 1988", section: "163A", title: "Special provisions as to payment of compensation on structured formula basis", content: "The owner of the motor vehicle or the authorized insurer shall be liable to pay in the case of death or permanent disablement due to accident arising out of the use of motor vehicle, compensation as indicated in the Second Schedule to the legal representatives or the victim, as the case may be.", keywords: ["structured compensation", "accident compensation formula", "motor accident tribunal"] },
  { act: "Motor Vehicles Act 1988", section: "177", title: "General provision for punishment of offences", content: "Whoever contravenes any provision of this Act or of any rule, regulation or notification made thereunder shall, if no penalty is provided for the offence, be punishable for the first offence with fine which may extend to five hundred rupees, and for any second or subsequent offence with fine which may extend to fifteen hundred rupees.", keywords: ["traffic fine", "traffic violation", "motor vehicle offence"] },
  { act: "Motor Vehicles Act 1988", section: "184", title: "Driving dangerously", content: "Whoever drives a motor vehicle at a speed or in a manner which is dangerous to the public, having regard to all the circumstances of the case including the nature, condition and use of the place where the vehicle is driven and the amount of traffic which actually is at the time or which might reasonably be expected to be in the place, shall be punishable for the first offence with imprisonment up to six months or fine up to one thousand rupees or both, and for second offence with imprisonment up to two years or fine up to two thousand rupees or both.", keywords: ["dangerous driving", "reckless driving", "road safety"] },
  { act: "Motor Vehicles Act 1988", section: "185", title: "Driving by a drunken person or by a person under the influence of drugs", content: "Whoever, while driving or attempting to drive a motor vehicle, has in his blood alcohol exceeding 30 mg per 100 ml of blood detected in a test by a breath analyser, shall be punishable for the first offence with imprisonment up to six months or fine up to ten thousand rupees or both, and for second offence within three years with imprisonment up to two years or fine up to fifteen thousand rupees or both.", keywords: ["drunk driving", "DUI", "alcohol driving", "drug driving"] },
  { act: "Motor Vehicles Act 1988", section: "187", title: "Punishment for offences relating to accident", content: "Whoever fails to comply with the duty to stop and report an accident and render assistance shall be punishable with imprisonment up to six months or fine up to five hundred rupees or both. In case of death, the punishment may extend to imprisonment up to two years or fine up to two thousand rupees or both.", keywords: ["hit and run", "accident fleeing", "failure to report accident"] },
  { act: "Motor Vehicles Act 1988", section: "196", title: "Driving uninsured vehicle", content: "Whoever drives a motor vehicle or causes or allows a motor vehicle to be driven in contravention of the provisions of section 39 regarding insurance shall be punishable with imprisonment which may extend to three months, or with fine which may extend to one thousand rupees, or with both.", keywords: ["uninsured vehicle", "no insurance", "driving without insurance"] },
  // ===== HINDU MARRIAGE ACT 1955 - 25 sections =====
  { act: "Hindu Marriage Act 1955", section: "5", title: "Conditions for a Hindu marriage", content: "A marriage may be solemnized between any two Hindus if neither party has a spouse living at the time of the marriage, neither party is incapable of giving a valid consent due to unsoundness of mind, the bridegroom has completed the age of twenty-one years and the bride the age of eighteen years at the time of the marriage.", keywords: ["Hindu marriage", "marriage conditions", "marriage age", "valid marriage"] },
  { act: "Hindu Marriage Act 1955", section: "7", title: "Ceremonies for a Hindu marriage", content: "A Hindu marriage may be solemnized in accordance with the customary rites and ceremonies of either party thereto. Where such rites and ceremonies include the Saptapadi (taking of seven steps by the bridegroom and the bride jointly before the sacred fire), the marriage becomes complete and binding when the seventh step is taken.", keywords: ["marriage ceremony", "saptapadi", "Hindu wedding", "sacred fire"] },
  { act: "Hindu Marriage Act 1955", section: "9", title: "Restitution of conjugal rights", content: "When either the husband or the wife has, without reasonable excuse, withdrawn from the society of the other, the aggrieved party may apply by petition to the district court for restitution of conjugal rights and the court, on being satisfied of the truth of the statements made in such petition and that there is no legal ground why the application should not be granted, may decree restitution of conjugal rights accordingly.", keywords: ["conjugal rights", "restitution", "separation", "marital rights"] },
  { act: "Hindu Marriage Act 1955", section: "11", title: "Void marriages", content: "Any marriage solemnized after the commencement of this Act shall be null and void and may, on a petition presented by either party thereto against the other party, be so declared by a decree of nullity if it contravenes any one of the conditions specified in clauses (i), (iv) and (v) of section 5.", keywords: ["void marriage", "null marriage", "invalid marriage", "nullity"] },
  { act: "Hindu Marriage Act 1955", section: "12", title: "Voidable marriages", content: "Any marriage solemnized may be annulled by a decree of nullity on the ground that the marriage has not been consummated owing to the impotence of the respondent, or that the consent of the petitioner was obtained by force or fraud.", keywords: ["voidable marriage", "annulment", "impotence", "fraud marriage"] },
  { act: "Hindu Marriage Act 1955", section: "13", title: "Divorce", content: "Any marriage solemnized may, on a petition presented by either the husband or the wife, be dissolved by a decree of divorce on the grounds that the other party has committed adultery, has treated the petitioner with cruelty, has deserted the petitioner for a continuous period of not less than two years, has ceased to be a Hindu by conversion to another religion, has been incurably of unsound mind, has been suffering from a virulent and incurable form of leprosy, has been suffering from venereal disease in a communicable form, has renounced the world by entering any religious order, or has not been heard of as being alive for a period of seven years or more.", keywords: ["divorce", "grounds for divorce", "Hindu divorce", "marriage dissolution"] },
  { act: "Hindu Marriage Act 1955", section: "13B", title: "Divorce by mutual consent", content: "Subject to the provisions of this Act a petition for dissolution of marriage by a decree of divorce may be presented to the district court by both the parties to a marriage together, whether such marriage was solemnized before or after the commencement of the Marriage Laws (Amendment) Act, 1976, on the ground that they have been living separately for a period of one year or more, that they have not been able to live together and that they have mutually agreed that the marriage should be dissolved.", keywords: ["mutual consent divorce", "mutual divorce", "consensual divorce"] },
  { act: "Hindu Marriage Act 1955", section: "15", title: "Divorced persons when may marry again", content: "When a marriage has been dissolved by a decree of divorce and either there is no right of appeal against the decree or, if there is such a right of appeal, the time for appealing has expired without an appeal having been presented, or an appeal has been presented but has been dismissed, it shall be lawful for either party to the marriage to marry again.", keywords: ["remarriage after divorce", "second marriage", "divorced remarriage"] },
  { act: "Hindu Marriage Act 1955", section: "24", title: "Maintenance pendente lite and expenses of proceedings", content: "Where in any proceeding under this Act it appears to the court that either the wife or the husband, as the case may be, has no independent income sufficient for her or his support and the necessary expenses of the proceeding, it may, on the application of the wife or the husband, order the respondent to pay to the petitioner the expenses of the proceeding, and monthly during the proceeding such sum as, having regard to the petitioner's own income and the income of the respondent, it may seem to the court to be reasonable.", keywords: ["maintenance", "alimony", "pendente lite", "interim maintenance"] },
  { act: "Hindu Marriage Act 1955", section: "25", title: "Permanent alimony and maintenance", content: "Any court exercising jurisdiction under this Act may, at the time of passing any decree or at any time subsequent thereto, on application made to it for the purpose by either the wife or the husband, order that the respondent shall pay to the applicant for her or his maintenance and support such gross sum or such monthly or periodical sum for a term not exceeding the life of the applicant as, having regard to the respondent's own income and other property, the income and other property of the applicant, the conduct of the parties and other circumstances of the case, it may seem to the court to be just.", keywords: ["permanent alimony", "maintenance", "spousal support", "divorce maintenance"] },
  // ===== DOMESTIC VIOLENCE ACT 2005 - 15 sections =====
  { act: "Protection of Women from Domestic Violence Act 2005", section: "3", title: "Definition of domestic violence", content: "Any act, omission or commission or conduct of the respondent shall constitute domestic violence in case it harms or injures or endangers the health, safety, life, limb or well-being, whether mental or physical, of the aggrieved person or tends to do so and includes causing physical abuse, sexual abuse, verbal and emotional abuse and economic abuse.", keywords: ["domestic violence", "physical abuse", "emotional abuse", "economic abuse"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "4", title: "Information to Protection Officer", content: "Any person who has reason to believe that an act of domestic violence has been, or is being, or is likely to be committed, may give information about it to the concerned Protection Officer.", keywords: ["protection officer", "domestic violence report", "DV complaint"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "12", title: "Application to Magistrate", content: "An aggrieved person or a Protection Officer or any other person on behalf of the aggrieved person may present an application to the Magistrate seeking one or more reliefs under this Act.", keywords: ["DV application", "magistrate", "domestic violence case"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "17", title: "Right to reside in a shared household", content: "Every woman in a domestic relationship shall have the right to reside in the shared household, whether or not she has any right, title or beneficial interest in the same.", keywords: ["right to reside", "shared household", "residence right"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "18", title: "Protection orders", content: "The Magistrate may, after giving the aggrieved person and the respondent an opportunity of being heard and on being prima facie satisfied that domestic violence has taken place or is likely to take place, pass a protection order in favour of the aggrieved person prohibiting the respondent from committing any act of domestic violence, aiding or abetting in the commission of acts of domestic violence, entering the place of employment or school of the aggrieved person.", keywords: ["protection order", "restraining order", "domestic violence order"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "19", title: "Residence orders", content: "The Magistrate may, on being satisfied that domestic violence has taken place, pass a residence order restraining the respondent from dispossessing or in any other manner disturbing the possession of the aggrieved person from the shared household, or directing the respondent to remove himself from the shared household.", keywords: ["residence order", "eviction order", "shared household order"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "20", title: "Monetary reliefs", content: "The aggrieved person may seek monetary relief to meet the expenses incurred and losses suffered by the aggrieved person and any child of the aggrieved person as a result of domestic violence including loss of earnings, medical expenses, loss caused due to destruction, damage or removal of any property from the control of the aggrieved person, and the maintenance for the aggrieved person as well as her children.", keywords: ["monetary relief", "compensation", "maintenance", "domestic violence damages"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "22", title: "Compensation orders", content: "In addition to other reliefs as may be granted under this Act, the Magistrate may on an application being made by the aggrieved person, pass an order directing the respondent to pay compensation and damages for the injuries, including mental torture and emotional distress, caused by the acts of domestic violence committed by that respondent.", keywords: ["compensation order", "mental torture compensation", "DV damages"] },
  { act: "Protection of Women from Domestic Violence Act 2005", section: "31", title: "Penalty for breach of protection order", content: "A breach of protection order, or of an interim protection order, by the respondent shall be an offence under this Act and shall be punishable with imprisonment of either description for a term which may extend to one year, or with fine which may extend to twenty thousand rupees, or with both.", keywords: ["breach of protection order", "DV penalty", "protection order violation"] },
  // ===== POCSO ACT 2012 - 15 sections =====
  { act: "POCSO Act 2012", section: "3", title: "Penetrative sexual assault", content: "A person is said to commit penetrative sexual assault if he commits any penetrative sexual act on a child who is under eighteen years of age.", keywords: ["penetrative sexual assault", "child sexual abuse", "POCSO"] },
  { act: "POCSO Act 2012", section: "4", title: "Punishment for penetrative sexual assault", content: "Whoever commits penetrative sexual assault shall be punished with imprisonment of either description for a term which shall not be less than ten years but which may extend to imprisonment for life, and shall also be liable to fine.", keywords: ["POCSO punishment", "child abuse punishment"] },
  { act: "POCSO Act 2012", section: "5", title: "Aggravated penetrative sexual assault", content: "Penetrative sexual assault is aggravated when committed by a police officer, member of armed forces, public servant, staff of jail or remand home, hospital or educational institution, or by a relative or person in a position of trust or authority of the child.", keywords: ["aggravated sexual assault", "position of trust", "authority abuse"] },
  { act: "POCSO Act 2012", section: "7", title: "Sexual assault", content: "Whoever, with sexual intent touches the vagina, penis, anus or breast of the child or makes the child touch the vagina, penis, anus or breast of such person or any other person, or does any other act with sexual intent which involves physical contact without penetration is said to commit sexual assault.", keywords: ["sexual assault child", "touching", "molestation child"] },
  { act: "POCSO Act 2012", section: "11", title: "Sexual harassment of child", content: "A person is said to commit sexual harassment upon a child when such person with sexual intent utters any word or makes any sound or gesture or exhibits any object or part of body with the intention that such word or sound shall be heard or such gesture or object or part of body shall be seen by the child, or makes a child exhibit his body or any part of his body, or shows any object to a child in any form for pornographic purposes, or repeatedly or constantly follows or watches or contacts a child either directly or through electronic, digital or any other means, or threatens to use any form of media for sexual purposes.", keywords: ["child sexual harassment", "child harassment", "POCSO harassment"] },
  { act: "POCSO Act 2012", section: "14", title: "Punishment for using child for pornographic purposes", content: "Whoever uses a child or children for pornographic purposes shall be punished with imprisonment for a term which shall not be less than five years and fine, and in the event of second or subsequent conviction with imprisonment not less than seven years and fine.", keywords: ["child pornography", "using child for pornography", "POCSO pornography"] },
  { act: "POCSO Act 2012", section: "19", title: "Reporting of offences", content: "Any person who has apprehension that an offence under this Act is likely to be committed or has knowledge that such an offence has been committed, he shall provide such information to the Special Juvenile Police Unit or the local police. Any person who fails to report the commission of an offence shall be punished with imprisonment up to six months or fine or both.", keywords: ["mandatory reporting", "POCSO reporting", "child abuse reporting"] },
  { act: "POCSO Act 2012", section: "21", title: "Punishment for false complaint", content: "Any person who makes false complaint or provides false information against any person in respect of an offence committed under sections 3, 5, 7 and 9, solely with the intention to humiliate, extort or threaten or defame him, shall be punished with imprisonment up to six months or fine or both.", keywords: ["false POCSO complaint", "false accusation", "POCSO misuse"] },
  { act: "POCSO Act 2012", section: "29", title: "Presumption as to certain offences", content: "Where a person is prosecuted for committing or abetting or attempting to commit any offence under sections 3, 5, 7 and 9 of this Act, the Special Court shall presume that such person has committed or abetted or attempted to commit the offence unless the contrary is proved.", keywords: ["POCSO presumption", "reverse burden of proof", "presumption of guilt"] },
  { act: "POCSO Act 2012", section: "33", title: "Procedure for recording statement of child", content: "The Magistrate or police officer shall not detain the child in the police station in the night for any reason. The statement of the child shall be recorded as spoken by the child. The child shall not be called repeatedly to testify.", keywords: ["child statement", "child testimony", "POCSO procedure"] },
  // ===== LABOUR LAWS - 30 sections =====
  { act: "Industrial Disputes Act 1947", section: "2(k)", title: "Strike defined", content: "Strike means a cessation of work by a body of persons employed in any industry acting in combination, or a concerted refusal, or a refusal under a common understanding, of any number of persons who are or have been so employed to continue to work or to accept employment.", keywords: ["strike", "work stoppage", "industrial action"] },
  { act: "Industrial Disputes Act 1947", section: "2(l)", title: "Lockout defined", content: "Lockout means the temporary closing of a place of employment, or the suspension of work, or the refusal by an employer to continue to employ any number of persons employed by him.", keywords: ["lockout", "employer lockout", "workplace closure"] },
  { act: "Industrial Disputes Act 1947", section: "9A", title: "Notice of change", content: "No employer, who proposes to effect any change in the conditions of service applicable to any workman in respect of any matter specified in the Fourth Schedule, shall effect such change without giving to the workmen likely to be affected by such change a notice in the prescribed manner of the nature of the change proposed to be effected, and within twenty-one days of giving such notice.", keywords: ["notice of change", "service conditions", "employment change"] },
  { act: "Industrial Disputes Act 1947", section: "10", title: "Reference of disputes to Boards, Courts or Tribunals", content: "Where the appropriate Government is of opinion that any industrial dispute exists or is apprehended, it may at any time by order in writing refer the dispute to a Board of Conciliation, or to a Court of Inquiry, or to a Labour Court, or to a Tribunal for adjudication.", keywords: ["industrial dispute", "labour court", "tribunal", "dispute resolution"] },
  { act: "Industrial Disputes Act 1947", section: "25F", title: "Conditions precedent to retrenchment of workmen", content: "No workman employed in any industry who has been in continuous service for not less than one year under an employer shall be retrenched by that employer until the workman has been given one month's notice in writing indicating the reasons for retrenchment and the period of notice has expired, or the workman has been paid in lieu of such notice wages for the period of the notice, and the workman has been paid at the time of retrenchment compensation which shall be equivalent to fifteen days' average pay for every completed year of continuous service.", keywords: ["retrenchment", "layoff", "termination notice", "severance pay"] },
  { act: "Industrial Disputes Act 1947", section: "25G", title: "Procedure for retrenchment", content: "Where any workman in an industrial establishment who is a citizen of India is to be retrenched and he belongs to a particular category of workmen in that establishment, the employer shall ordinarily retrench the workman who was the last person to be employed in that category, unless for reasons to be recorded the employer retrenches any other workman.", keywords: ["last in first out", "LIFO", "retrenchment procedure"] },
  { act: "Industrial Disputes Act 1947", section: "25N", title: "Conditions precedent to retrenchment in certain establishments", content: "No workman employed in any industrial establishment to which this Chapter applies shall be retrenched until three months' notice has been given to the appropriate Government and the appropriate Government has granted permission for such retrenchment.", keywords: ["government permission", "retrenchment permission", "large establishment"] },
  { act: "Minimum Wages Act 1948", section: "3", title: "Fixing of minimum rates of wages", content: "The appropriate Government shall fix the minimum rates of wages payable to employees employed in an employment specified in Part I or Part II of the Schedule and in an employment added to either Part by notification.", keywords: ["minimum wage", "wage fixing", "minimum pay"] },
  { act: "Minimum Wages Act 1948", section: "12", title: "Payment of minimum wages", content: "The employer shall pay to every employee engaged in a scheduled employment under him wages at a rate not less than the minimum rate of wages fixed by such notification for that class of employees in that employment without any deductions except as may be authorized.", keywords: ["minimum wage payment", "wage compliance", "employer obligation"] },
  { act: "Minimum Wages Act 1948", section: "22", title: "Penalties for certain offences", content: "Any employer who pays to any employee less than the minimum rates of wages fixed for that employee's class of work, or makes any deduction from the wages which is not authorized to be made, shall be punishable with imprisonment up to six months, or with fine up to five hundred rupees, or with both.", keywords: ["minimum wage violation", "underpayment penalty", "wage theft"] },
  { act: "Payment of Wages Act 1936", section: "3", title: "Responsibility for payment of wages", content: "Every employer shall be responsible for the payment to persons employed by him of all wages required to be paid under this Act.", keywords: ["wage payment", "employer responsibility", "salary payment"] },
  { act: "Payment of Wages Act 1936", section: "5", title: "Time of payment of wages", content: "The wages of every person employed upon or in any railway, factory or industrial or other establishment upon or in which less than one thousand persons are employed shall be paid before the expiry of the seventh day after the last day of the wage period. In other cases before the expiry of the tenth day.", keywords: ["wage payment time", "salary date", "payment deadline"] },
  { act: "Payment of Wages Act 1936", section: "7", title: "Deductions which may be made from wages", content: "The wages of an employed person shall be paid to him without deductions of any kind except those authorized by or under this Act. Authorized deductions include fines, deductions for absence from duty, deductions for damage to or loss of goods, deductions for house-accommodation, deductions for amenities and services, deductions for recovery of advances, deductions for income-tax payable, and deductions for payment to co-operative societies.", keywords: ["wage deduction", "salary deduction", "authorized deductions"] },
  { act: "Payment of Gratuity Act 1972", section: "4", title: "Payment of gratuity", content: "Gratuity shall be payable to an employee on the termination of his employment after he has rendered continuous service for not less than five years on his superannuation, or on his retirement or resignation, or on his death or disablement due to accident or disease. The employer shall pay gratuity to an employee at the rate of fifteen days' wages based on the rate of wages last drawn by the employee concerned for every completed year of service or part thereof in excess of six months.", keywords: ["gratuity", "gratuity payment", "retirement benefit", "five years service"] },
  { act: "Payment of Gratuity Act 1972", section: "4(6)", title: "Maximum gratuity amount", content: "The amount of gratuity payable to an employee shall not exceed twenty lakh rupees.", keywords: ["gratuity limit", "maximum gratuity", "gratuity cap"] },
  { act: "Employees Provident Fund Act 1952", section: "6", title: "Contributions and matters which may be provided for in Schemes", content: "The contribution which shall be paid by the employer to the Fund shall be twelve per cent of the basic wages, dearness allowance and retaining allowance if any, for the time being payable to each of the employees, and the employees' contribution shall be equal to the contribution payable by the employer.", keywords: ["provident fund", "PF contribution", "EPF", "12 percent"] },
  { act: "Maternity Benefit Act 1961", section: "5", title: "Right to payment of maternity benefit", content: "Every woman shall be entitled to, and her employer shall be liable for, the payment of maternity benefit at the rate of the average daily wage for the period of her actual absence, that is to say, the period immediately preceding the day of her delivery, the actual day of her delivery and any period immediately following that day. The maximum period for which any woman shall be entitled to maternity benefit shall be twenty-six weeks of which not more than eight weeks shall precede the date of her expected delivery.", keywords: ["maternity benefit", "maternity leave", "26 weeks", "pregnancy leave"] },
  { act: "Maternity Benefit Act 1961", section: "11A", title: "Creche facility", content: "Every establishment having fifty or more employees shall have the facility of creche within such distance as may be prescribed, either separately or along with common facilities.", keywords: ["creche", "childcare", "workplace creche", "working mothers"] },
  { act: "Equal Remuneration Act 1976", section: "4", title: "Duty of employer to pay equal remuneration", content: "No employer shall pay to any worker, employed by him in an establishment or employment, remuneration, whether payable in cash or in kind, at rates less favourable than those at which remuneration is paid by him to the workers of the opposite sex in such establishment or employment for performing the same work or work of a similar nature.", keywords: ["equal pay", "gender pay gap", "equal remuneration", "pay discrimination"] },
  { act: "Child Labour (Prohibition and Regulation) Act 1986", section: "3", title: "Prohibition of employment of children in certain occupations", content: "No child below the age of fourteen years shall be employed or permitted to work in any occupation set forth in Part A of the Schedule or in any workshop wherein any of the processes set forth in Part B of the Schedule is carried on.", keywords: ["child labour", "child employment", "minor employment", "child work prohibition"] },
  // ===== CONSTITUTION OF INDIA - FUNDAMENTAL RIGHTS - 30 sections =====
  { act: "Constitution of India", section: "Article 14", title: "Equality before law", content: "The State shall not deny to any person equality before the law or the equal protection of the laws within the territory of India.", keywords: ["equality", "equal protection", "fundamental right", "discrimination"] },
  { act: "Constitution of India", section: "Article 15", title: "Prohibition of discrimination", content: "The State shall not discriminate against any citizen on grounds only of religion, race, caste, sex, place of birth or any of them. No citizen shall, on grounds only of religion, race, caste, sex, place of birth or any of them, be subject to any disability, liability, restriction or condition with regard to access to shops, public restaurants, hotels and places of public entertainment, or the use of wells, tanks, bathing ghats, roads and places of public resort maintained wholly or partly out of State funds.", keywords: ["discrimination", "caste discrimination", "gender discrimination", "equality"] },
  { act: "Constitution of India", section: "Article 16", title: "Equality of opportunity in public employment", content: "There shall be equality of opportunity for all citizens in matters relating to employment or appointment to any office under the State. No citizen shall, on grounds only of religion, race, caste, sex, descent, place of birth, residence or any of them, be ineligible for, or discriminated against in respect of, any employment or office under the State.", keywords: ["employment equality", "government job", "reservation", "public employment"] },
  { act: "Constitution of India", section: "Article 17", title: "Abolition of Untouchability", content: "Untouchability is abolished and its practice in any form is forbidden. The enforcement of any disability arising out of Untouchability shall be an offence punishable in accordance with law.", keywords: ["untouchability", "caste system", "dalit rights", "social justice"] },
  { act: "Constitution of India", section: "Article 19", title: "Protection of certain rights regarding freedom of speech", content: "All citizens shall have the right to freedom of speech and expression, to assemble peaceably and without arms, to form associations or unions, to move freely throughout the territory of India, to reside and settle in any part of the territory of India, and to practise any profession, or to carry on any occupation, trade or business.", keywords: ["free speech", "freedom of expression", "right to protest", "freedom of movement", "right to work"] },
  { act: "Constitution of India", section: "Article 20", title: "Protection in respect of conviction for offences", content: "No person shall be convicted of any offence except for violation of a law in force at the time of the commission of the act charged as an offence, nor be subjected to a penalty greater than that which might have been inflicted under the law in force at the time of the commission of the offence. No person shall be prosecuted and punished for the same offence more than once. No person accused of any offence shall be compelled to be a witness against himself.", keywords: ["double jeopardy", "self-incrimination", "ex post facto", "criminal protection"] },
  { act: "Constitution of India", section: "Article 21", title: "Protection of life and personal liberty", content: "No person shall be deprived of his life or personal liberty except according to procedure established by law.", keywords: ["right to life", "personal liberty", "fundamental right", "due process"] },
  { act: "Constitution of India", section: "Article 21A", title: "Right to education", content: "The State shall provide free and compulsory education to all children of the age of six to fourteen years in such manner as the State may, by law, determine.", keywords: ["right to education", "free education", "compulsory education", "children education"] },
  { act: "Constitution of India", section: "Article 22", title: "Protection against arrest and detention", content: "No person who is arrested shall be detained in custody without being informed, as soon as may be, of the grounds for such arrest nor shall he be denied the right to consult, and to be defended by, a legal practitioner of his choice. Every person who is arrested and detained in custody shall be produced before the nearest magistrate within a period of twenty-four hours.", keywords: ["arrest rights", "detention", "right to lawyer", "24 hours magistrate"] },
  { act: "Constitution of India", section: "Article 23", title: "Prohibition of traffic in human beings and forced labour", content: "Traffic in human beings and begar and other similar forms of forced labour are prohibited and any contravention of this provision shall be an offence punishable in accordance with law.", keywords: ["human trafficking", "forced labour", "bonded labour", "slavery"] },
  { act: "Constitution of India", section: "Article 24", title: "Prohibition of employment of children in factories", content: "No child below the age of fourteen years shall be employed to work in any factory or mine or engaged in any other hazardous employment.", keywords: ["child labour", "factory employment", "hazardous work", "child protection"] },
  { act: "Constitution of India", section: "Article 25", title: "Freedom of conscience and free profession, practice and propagation of religion", content: "Subject to public order, morality and health, all persons are equally entitled to freedom of conscience and the right freely to profess, practise and propagate religion.", keywords: ["religious freedom", "freedom of religion", "right to worship", "propagation"] },
  { act: "Constitution of India", section: "Article 29", title: "Protection of interests of minorities", content: "Any section of the citizens residing in the territory of India or any part thereof having a distinct language, script or culture of its own shall have the right to conserve the same. No citizen shall be denied admission into any educational institution maintained by the State or receiving aid out of State funds on grounds only of religion, race, caste, language or any of them.", keywords: ["minority rights", "cultural rights", "language rights", "educational rights"] },
  { act: "Constitution of India", section: "Article 32", title: "Remedies for enforcement of fundamental rights", content: "The right to move the Supreme Court by appropriate proceedings for the enforcement of the rights conferred by this Part is guaranteed. The Supreme Court shall have power to issue directions or orders or writs, including writs in the nature of habeas corpus, mandamus, prohibition, quo warranto and certiorari, whichever may be appropriate, for the enforcement of any of the rights conferred by this Part.", keywords: ["writ petition", "Supreme Court", "habeas corpus", "mandamus", "fundamental rights enforcement"] },
  { act: "Constitution of India", section: "Article 44", title: "Uniform civil code", content: "The State shall endeavour to secure for the citizens a uniform civil code throughout the territory of India.", keywords: ["uniform civil code", "UCC", "civil code", "personal law"] },
  { act: "Constitution of India", section: "Article 226", title: "Power of High Courts to issue certain writs", content: "Every High Court shall have power to issue to any person or authority, including in appropriate cases any Government, within those territories directions, orders or writs, including writs in the nature of habeas corpus, mandamus, prohibition, quo warranto and certiorari for the enforcement of any of the rights conferred by Part III and for any other purpose.", keywords: ["High Court writ", "writ jurisdiction", "habeas corpus", "mandamus"] },
  { act: "Constitution of India", section: "Article 300A", title: "Right to property", content: "No person shall be deprived of his property save by authority of law.", keywords: ["right to property", "property rights", "land acquisition"] },
  { act: "Constitution of India", section: "Article 370", title: "Special provisions for Jammu and Kashmir (Abrogated)", content: "Article 370 which granted special autonomous status to Jammu and Kashmir was effectively abrogated on 5 August 2019 by a Presidential Order. The special status including separate constitution, separate flag, and autonomy over all matters except defence, foreign affairs and communications was revoked.", keywords: ["Article 370", "Jammu Kashmir", "special status", "abrogation"] },
  // ===== NEGOTIABLE INSTRUMENTS ACT 1881 - 10 sections =====
  { act: "Negotiable Instruments Act 1881", section: "138", title: "Dishonour of cheque for insufficiency of funds", content: "Where any cheque drawn by a person on an account maintained by him with a banker for payment of any amount of money to another person from out of that account for the discharge, in whole or in part, of any debt or other liability, is returned by the bank unpaid, either because of the amount of money standing to the credit of that account is insufficient to honour the cheque or that it exceeds the amount arranged to be paid from that account by an agreement made with that bank, such person shall be deemed to have committed an offence and shall be punished with imprisonment up to two years, or with fine which may extend to twice the amount of the cheque, or with both.", keywords: ["cheque bounce", "dishonoured cheque", "bounced cheque", "138 NI Act"] },
  { act: "Negotiable Instruments Act 1881", section: "139", title: "Presumption in favour of holder", content: "It shall be presumed, unless the contrary is proved, that the holder of a cheque received the cheque of the nature referred to in section 138 for the discharge, in whole or in part, of any debt or other liability.", keywords: ["cheque presumption", "holder rights", "cheque bounce presumption"] },
  { act: "Negotiable Instruments Act 1881", section: "141", title: "Offences by companies", content: "If the person committing an offence under section 138 is a company, every person who, at the time the offence was committed, was in charge of, and was responsible to, the company for the conduct of the business of the company, as well as the company, shall be deemed to be guilty of the offence.", keywords: ["company cheque bounce", "director liability", "corporate offence"] },
  { act: "Negotiable Instruments Act 1881", section: "142", title: "Cognizance of offences", content: "No court shall take cognizance of any offence punishable under section 138 except upon a complaint, in writing, made by the payee or the holder in due course of the cheque. Such complaint is to be made within one month of the date on which the cause of action arises.", keywords: ["cheque bounce complaint", "limitation period", "cognizance"] },
  // ===== SPECIFIC RELIEF ACT 1963 - 10 sections =====
  { act: "Specific Relief Act 1963", section: "6", title: "Suit by person dispossessed of immoveable property", content: "If any person is dispossessed without his consent of immoveable property otherwise than in due course of law, he or any person claiming through him may, by suit, recover possession thereof, notwithstanding any other title that may be set up in such suit.", keywords: ["property dispossession", "land dispute", "possession recovery"] },
  { act: "Specific Relief Act 1963", section: "10", title: "Specific performance in respect of contracts", content: "The specific performance of a contract shall be enforced by the court subject to the provisions contained in sub-section (2) of section 11, section 14 and section 16.", keywords: ["specific performance", "contract enforcement", "court order"] },
  { act: "Specific Relief Act 1963", section: "14", title: "Contracts not specifically enforceable", content: "The following contracts cannot be specifically enforced: a contract for the non-performance of which compensation in money is an adequate relief, a contract which runs into such minute or numerous details or which is so dependent on the personal qualifications or volition of the parties, or otherwise from its nature is such that the court cannot enforce specific performance of its material terms, a contract which is in its nature determinable, a contract the performance of which involves the performance of a continuous duty which the court cannot supervise.", keywords: ["non-enforceable contract", "specific performance exception"] },
  { act: "Specific Relief Act 1963", section: "36", title: "Preventive relief how granted", content: "Preventive relief is granted at the discretion of the court by injunction, temporary or perpetual.", keywords: ["injunction", "preventive relief", "court injunction", "temporary injunction"] },
  { act: "Specific Relief Act 1963", section: "38", title: "Perpetual injunction when granted", content: "The plaintiff is entitled to a perpetual injunction when the defendant invades or threatens to invade the plaintiff's right to, or enjoyment of, property, or the defendant is in breach of an obligation existing in his favour.", keywords: ["perpetual injunction", "permanent injunction", "property protection"] },
  // ===== INDIAN EVIDENCE ACT 1872 - 15 sections =====
  { act: "Indian Evidence Act 1872", section: "3", title: "Interpretation clause - Evidence", content: "Evidence means and includes all statements which the Court permits or requires to be made before it by witnesses in relation to matters of fact under inquiry (oral evidence), and all documents including electronic records produced for the inspection of the Court (documentary evidence).", keywords: ["evidence", "oral evidence", "documentary evidence", "electronic records"] },
  { act: "Indian Evidence Act 1872", section: "17", title: "Admission defined", content: "An admission is a statement, oral or documentary or contained in electronic form, which suggests any inference as to any fact in issue or relevant fact, and which is made by any of the persons, and under the circumstances, hereinafter mentioned.", keywords: ["admission", "statement", "confession"] },
  { act: "Indian Evidence Act 1872", section: "24", title: "Confession caused by inducement, threat or promise", content: "A confession made by an accused person is irrelevant in a criminal proceeding, if the making of the confession appears to the Court to have been caused by any inducement, threat or promise having reference to the charge against the accused person, proceeding from a person in authority.", keywords: ["forced confession", "coerced confession", "involuntary confession"] },
  { act: "Indian Evidence Act 1872", section: "25", title: "Confession to police officer not to be proved", content: "No confession made to a police officer shall be proved as against a person accused of any offence.", keywords: ["police confession", "confession inadmissible", "police statement"] },
  { act: "Indian Evidence Act 1872", section: "27", title: "How much of information received from accused may be proved", content: "Provided that, when any fact is deposed to as discovered in consequence of information received from a person accused of any offence, in the custody of a police officer, so much of such information, whether it amounts to a confession or not, as relates distinctly to the fact thereby discovered, may be proved.", keywords: ["discovery statement", "accused information", "fact discovery"] },
  { act: "Indian Evidence Act 1872", section: "45", title: "Opinions of experts", content: "When the Court has to form an opinion upon a point of foreign law or of science or art, or as to identity of handwriting or finger impressions, the opinions upon that point of persons specially skilled in such foreign law, science or art, or in questions as to identity of handwriting or finger impressions are relevant facts. Such persons are called experts.", keywords: ["expert opinion", "expert witness", "forensic evidence", "handwriting expert"] },
  { act: "Indian Evidence Act 1872", section: "65B", title: "Admissibility of electronic records", content: "Any information contained in an electronic record which is printed on a paper, stored, recorded or copied in optical or magnetic media produced by a computer shall be deemed to be also a document, if the conditions mentioned in this section are satisfied in relation to the information and computer in question and shall be admissible in any proceedings, without further proof or production of the original.", keywords: ["electronic evidence", "digital evidence", "computer records", "electronic records admissibility"] },
  { act: "Indian Evidence Act 1872", section: "101", title: "Burden of proof", content: "Whoever desires any Court to give judgment as to any legal right or liability dependent on the existence of facts which he asserts, must prove that those facts exist. When a person is bound to prove the existence of any fact, it is said that the burden of proof lies on that person.", keywords: ["burden of proof", "onus of proof", "proving facts"] },
  { act: "Indian Evidence Act 1872", section: "113A", title: "Presumption as to abetment of suicide by a married woman", content: "When the question is whether the commission of suicide by a woman had been abetted by her husband or any relative of her husband and it is shown that she had committed suicide within a period of seven years from the date of her marriage and that her husband or such relative of her husband had subjected her to cruelty, the court may presume that such suicide had been abetted by her husband or by such relative of her husband.", keywords: ["suicide presumption", "married woman suicide", "dowry death presumption"] },
  { act: "Indian Evidence Act 1872", section: "114A", title: "Presumption as to absence of consent in certain prosecutions for rape", content: "In a prosecution for rape where sexual intercourse by the accused is proved and the question is whether it was without the consent of the woman alleged to have been raped and such woman states in her evidence before the Court that she did not consent, the Court shall presume that she did not consent.", keywords: ["rape presumption", "consent presumption", "rape evidence"] },
  // ===== CODE OF CRIMINAL PROCEDURE (CrPC) - 30 sections =====
  { act: "Code of Criminal Procedure 1973", section: "41", title: "When police may arrest without warrant", content: "Any police officer may without an order from a Magistrate and without a warrant, arrest any person who has been concerned in any cognizable offence, or against whom a reasonable complaint has been made, or credible information has been received, or a reasonable suspicion exists, of his having been so concerned.", keywords: ["arrest without warrant", "police arrest", "cognizable offence"] },
  { act: "Code of Criminal Procedure 1973", section: "41A", title: "Notice of appearance before police officer", content: "The police officer shall, in all cases where the arrest of a person is not required under the provisions of sub-section (1) of section 41, issue a notice directing the person against whom a reasonable complaint has been made, or credible information has been received, or a reasonable suspicion exists that he has committed a cognizable offence, to appear before him or at such other place as may be specified in the notice.", keywords: ["notice to appear", "police notice", "41A notice"] },
  { act: "Code of Criminal Procedure 1973", section: "46", title: "How arrest is made", content: "In making an arrest the police officer or other person making the same shall actually touch or confine the body of the person to be arrested, unless there be a submission to the custody by word or action. If such person forcibly resists the endeavour to arrest him, or attempts to evade the arrest, such police officer or other person may use all means necessary to effect the arrest.", keywords: ["arrest procedure", "how to arrest", "use of force"] },
  { act: "Code of Criminal Procedure 1973", section: "50", title: "Person arrested to be informed of grounds of arrest", content: "Every police officer or other person arresting any person without warrant shall forthwith communicate to him full particulars of the offence for which he is arrested or other grounds for such arrest. Where a police officer arrests without warrant any person other than a person accused of a non-bailable offence, he shall inform the person arrested that he is entitled to be released on bail.", keywords: ["arrest rights", "grounds of arrest", "bail information"] },
  { act: "Code of Criminal Procedure 1973", section: "57", title: "Person arrested not to be detained more than twenty-four hours", content: "No police officer shall detain in custody a person arrested without warrant for a longer period than under all the circumstances of the case is reasonable, and such period shall not, in the absence of a special order of a Magistrate under section 167, exceed twenty-four hours exclusive of the time necessary for the journey from the place of arrest to the Magistrate's Court.", keywords: ["24 hour detention", "police custody limit", "detention period"] },
  { act: "Code of Criminal Procedure 1973", section: "125", title: "Order for maintenance of wives, children and parents", content: "If any person having sufficient means neglects or refuses to maintain his wife, unable to maintain herself, or his legitimate or illegitimate minor child, whether married or not, unable to maintain itself, or his legitimate or illegitimate child who has attained majority where such child is by reason of any physical or mental abnormality or injury unable to maintain itself, or his father or mother, unable to maintain himself or herself, a Magistrate of the first class may, upon proof of such neglect or refusal, order such person to make a monthly allowance for the maintenance of his wife or such child, father or mother.", keywords: ["maintenance", "wife maintenance", "child maintenance", "parent maintenance", "alimony"] },
  { act: "Code of Criminal Procedure 1973", section: "144", title: "Power to issue order in urgent cases of nuisance or apprehended danger", content: "In cases where, in the opinion of a District Magistrate, a Sub-divisional Magistrate, or any other Executive Magistrate specially empowered by the State Government, there is sufficient ground for proceeding under this section and immediate prevention or speedy remedy is desirable, such Magistrate may, by a written order stating the material facts of the case, direct any person to abstain from a certain act or to take certain order with respect to certain property in his possession or under his management, if such Magistrate considers that such direction is likely to prevent, or tends to prevent, obstruction, annoyance or injury to any person lawfully employed, or danger to human life, health or safety, or a disturbance of the public tranquillity, or a riot, or an affray.", keywords: ["Section 144", "curfew", "prohibitory orders", "public order", "emergency order"] },
  { act: "Code of Criminal Procedure 1973", section: "154", title: "Information in cognizable cases (FIR)", content: "Every information relating to the commission of a cognizable offence, if given orally to an officer in charge of a police station, shall be reduced to writing by him or under his direction, and be read over to the informant; and every such information, whether given in writing or reduced to writing as aforesaid, shall be signed by the person giving it, and the substance thereof shall be entered in a book to be kept by such officer in such form as the State Government may prescribe in this behalf.", keywords: ["FIR", "First Information Report", "police complaint", "cognizable offence report"] },
  { act: "Code of Criminal Procedure 1973", section: "155", title: "Information as to non-cognizable cases", content: "When information is given to an officer in charge of a police station of the commission within the limits of such station of a non-cognizable offence, he shall enter or cause to be entered the substance of the information in a book to be kept by such officer in such form as the State Government may prescribe in this behalf, and refer the informant to the Magistrate.", keywords: ["non-cognizable offence", "NCR", "police diary"] },
  { act: "Code of Criminal Procedure 1973", section: "161", title: "Examination of witnesses by police", content: "Any police officer making an investigation under this Chapter, or any police officer not below such rank as the State Government may, by general or special order, prescribe in this behalf, acting on the requisition of such officer, may examine orally any person supposed to be acquainted with the facts and circumstances of the case.", keywords: ["police investigation", "witness examination", "police questioning"] },
  { act: "Code of Criminal Procedure 1973", section: "164", title: "Recording of confessions and statements", content: "Any Metropolitan Magistrate or Judicial Magistrate may, whether or not he has jurisdiction in the case, record any confession or statement made to him in the course of an investigation under this Chapter or under any other law for the time being in force, or at any time afterwards before the commencement of the inquiry or trial.", keywords: ["confession recording", "magistrate statement", "164 statement"] },
  { act: "Code of Criminal Procedure 1973", section: "167", title: "Procedure when investigation cannot be completed in twenty-four hours", content: "Whenever any person is arrested and detained in custody, and it appears that the investigation cannot be completed within the period of twenty-four hours, and there are grounds for believing that the accusation or information is well-founded, the officer in charge of the police station or the police officer making the investigation shall forthwith transmit to the nearest Judicial Magistrate a copy of the entries in the diary and shall at the same time forward the accused to such Magistrate.", keywords: ["police remand", "judicial custody", "investigation extension", "remand"] },
  { act: "Code of Criminal Procedure 1973", section: "173", title: "Report of police officer on completion of investigation (Chargesheet)", content: "Every investigation under this Chapter shall be completed without unnecessary delay. As soon as it is completed, the officer in charge of the police station shall forward to a Magistrate empowered to take cognizance of the offence on a police report, a report in the form prescribed by the State Government.", keywords: ["chargesheet", "police report", "investigation completion", "final report"] },
  { act: "Code of Criminal Procedure 1973", section: "190", title: "Cognizance of offences by Magistrates", content: "Any Magistrate of the first class, and any Magistrate of the second class specially empowered in this behalf, may take cognizance of any offence upon receiving a complaint of facts which constitute such offence, upon a police report of such facts, or upon information received from any person other than a police officer, or upon his own knowledge, that such offence has been committed.", keywords: ["cognizance", "magistrate jurisdiction", "taking cognizance"] },
  { act: "Code of Criminal Procedure 1973", section: "197", title: "Prosecution of Judges and public servants", content: "When any person who is or was a Judge or Magistrate or a public servant not removable from his office save by or with the sanction of the Government is accused of any offence alleged to have been committed by him while acting or purporting to act in the discharge of his official duty, no Court shall take cognizance of such offence except with the previous sanction of the Central Government or the State Government.", keywords: ["government sanction", "public servant prosecution", "judge prosecution"] },
  { act: "Code of Criminal Procedure 1973", section: "200", title: "Examination of complainant", content: "A Magistrate taking cognizance of an offence on complaint shall examine upon oath the complainant and the witnesses present, if any, and the substance of such examination shall be reduced to writing and shall be signed by the complainant and the witnesses, and also by the Magistrate.", keywords: ["complaint examination", "magistrate examination", "complainant oath"] },
  { act: "Code of Criminal Procedure 1973", section: "227", title: "Discharge", content: "If, upon consideration of the record of the case and the documents submitted therewith, and after hearing the submissions of the accused and the prosecution, the Judge considers that there is not sufficient ground for proceeding against the accused, he shall discharge the accused and record his reasons for so doing.", keywords: ["discharge", "case discharge", "insufficient evidence"] },
  { act: "Code of Criminal Procedure 1973", section: "235", title: "Judgment of acquittal or conviction", content: "After hearing arguments and points of law, if any, the Judge shall give a judgment in the case. If the accused is convicted, the Judge shall, unless he proceeds in accordance with the provisions of section 360, hear the accused on the question of sentence, and then pass sentence on him according to law.", keywords: ["judgment", "conviction", "acquittal", "sentencing"] },
  { act: "Code of Criminal Procedure 1973", section: "313", title: "Power to examine the accused", content: "In every inquiry or trial, for the purpose of enabling the accused personally to explain any circumstances appearing in the evidence against him, the Court may at any stage, without previously warning the accused, put such questions to him as the Court considers necessary, and shall, after the witnesses for the prosecution have been examined and before he is called on for his defence, question him generally on the case.", keywords: ["accused examination", "court questioning", "313 statement"] },
  { act: "Code of Criminal Procedure 1973", section: "354", title: "Language and contents of judgment", content: "Every judgment shall be written in the language of the Court. Every judgment shall contain the point or points for determination, the decision thereon and the reasons for the decision. It shall be dated and signed by the presiding officer of the Court.", keywords: ["judgment format", "court judgment", "judgment requirements"] },
  { act: "Code of Criminal Procedure 1973", section: "374", title: "Appeals from convictions", content: "Any person convicted on a trial held by a High Court in its extraordinary original criminal jurisdiction may appeal to the Supreme Court. Any person convicted on a trial held by a Sessions Judge or an Additional Sessions Judge may appeal to the High Court.", keywords: ["criminal appeal", "appeal conviction", "High Court appeal"] },
  { act: "Code of Criminal Procedure 1973", section: "389", title: "Suspension of sentence pending appeal; release of appellant on bail", content: "Pending any appeal by a convicted person, the Appellate Court may, for reasons to be recorded by it in writing, order that the execution of the sentence or order appealed against be suspended and, also, if he is in confinement, that he be released on bail, or on his own bond.", keywords: ["bail pending appeal", "sentence suspension", "appeal bail"] },
  { act: "Code of Criminal Procedure 1973", section: "436", title: "In what cases bail to be taken", content: "When any person other than a person accused of a non-bailable offence is arrested or detained without warrant by an officer in charge of a police station, or appears or is brought before a Court, and is prepared at any time while in the custody of such officer or at any stage of the proceeding before such Court to give bail, such person shall be released on bail.", keywords: ["bail", "bailable offence", "release on bail"] },
  { act: "Code of Criminal Procedure 1973", section: "437", title: "When bail may be taken in case of non-bailable offence", content: "When any person accused of, or suspected of, the commission of any non-bailable offence is arrested or detained without warrant by an officer in charge of a police station or appears or is brought before a Court other than the High Court or Court of Session, he may be released on bail, but he shall not be so released if there appear reasonable grounds for believing that he has been guilty of an offence punishable with death or imprisonment for life.", keywords: ["non-bailable offence bail", "bail conditions", "bail hearing"] },
  { act: "Code of Criminal Procedure 1973", section: "438", title: "Direction for grant of bail to person apprehending arrest (Anticipatory bail)", content: "Where any person has reason to believe that he may be arrested on accusation of having committed a non-bailable offence, he may apply to the High Court or the Court of Session for a direction under this section that in the event of such arrest, he shall be released on bail.", keywords: ["anticipatory bail", "pre-arrest bail", "advance bail"] },
  { act: "Code of Criminal Procedure 1973", section: "439", title: "Special powers of High Court or Court of Session regarding bail", content: "A High Court or Court of Session may direct that any person accused of an offence and in custody be released on bail, and if the offence is of the nature specified in sub-section (3) of section 437, may impose any condition which it considers necessary.", keywords: ["High Court bail", "Sessions Court bail", "bail powers"] },
  { act: "Code of Criminal Procedure 1973", section: "482", title: "Saving of inherent powers of High Court", content: "Nothing in this Code shall be deemed to limit or affect the inherent powers of the High Court to make such orders as may be necessary to give effect to any order under this Code, or to prevent abuse of the process of any Court or otherwise to secure the ends of justice.", keywords: ["inherent powers", "High Court powers", "quashing", "482 petition"] },
  // ===== ADDITIONAL IMPORTANT ACTS - 60 sections =====
  { act: "Dowry Prohibition Act 1961", section: "2", title: "Definition of dowry", content: "Dowry means any property or valuable security given or agreed to be given either directly or indirectly by one party to a marriage to the other party to the marriage, or by the parents of either party to a marriage or by any other person, to either party to the marriage or to any other person, at or before or any time after the marriage in connection with the marriage of the said parties.", keywords: ["dowry", "dowry definition", "marriage gift", "dowry prohibition"] },
  { act: "Dowry Prohibition Act 1961", section: "3", title: "Penalty for giving or taking dowry", content: "If any person, after the commencement of this Act, gives or takes or abets the giving or taking of dowry, he shall be punishable with imprisonment for a term which shall not be less than five years, and with fine which shall not be less than fifteen thousand rupees or the amount of the value of such dowry, whichever is more.", keywords: ["dowry penalty", "giving dowry", "taking dowry", "dowry punishment"] },
  { act: "Dowry Prohibition Act 1961", section: "4", title: "Penalty for demanding dowry", content: "If any person demands, directly or indirectly, from the parents or other relatives or guardian of a bride or bridegroom, as the case may be, any dowry, he shall be punishable with imprisonment for a term which shall not be less than six months but which may extend to two years and with fine which may extend to ten thousand rupees.", keywords: ["dowry demand", "demanding dowry", "dowry demand penalty"] },
  { act: "SC/ST Prevention of Atrocities Act 1989", section: "3", title: "Punishments for offences of atrocities", content: "Whoever, not being a member of a Scheduled Caste or a Scheduled Tribe, forces a member of a Scheduled Caste or a Scheduled Tribe to drink or eat any inedible or obnoxious substance, or dumps excreta, sewage, carcasses or any other obnoxious substance in premises or neighbourhood, or forcibly removes clothes from the person of a member of a Scheduled Caste or a Scheduled Tribe or parades him naked or with painted face or body, or wrongfully occupies or cultivates any land owned by or allotted to a member of a Scheduled Caste or a Scheduled Tribe, shall be punishable with imprisonment for a term which shall not be less than six months but which may extend to five years and with fine.", keywords: ["SC ST atrocity", "caste atrocity", "dalit atrocity", "scheduled caste", "scheduled tribe"] },
  { act: "SC/ST Prevention of Atrocities Act 1989", section: "3(1)(r)", title: "Intentionally insulting or intimidating SC/ST member", content: "Whoever, not being a member of a Scheduled Caste or a Scheduled Tribe, intentionally insults or intimidates with intent to humiliate a member of a Scheduled Caste or a Scheduled Tribe in any place within public view, shall be punishable with imprisonment for a term which shall not be less than six months but which may extend to five years and with fine.", keywords: ["caste insult", "SC ST humiliation", "caste discrimination offence"] },
  { act: "Prevention of Corruption Act 1988", section: "7", title: "Offence relating to public servant being bribed", content: "Any public servant who obtains or accepts or attempts to obtain from any person, an undue advantage, with the intention to perform or cause performance of public duty improperly or dishonestly or to forbear or cause forbearance to perform such duty either by himself or by another public servant, shall be punishable with imprisonment for a term which shall not be less than three years but which may extend to seven years and shall also be liable to fine.", keywords: ["bribery", "corruption", "public servant bribe", "government corruption"] },
  { act: "Prevention of Corruption Act 1988", section: "8", title: "Offence relating to bribing a public servant", content: "Any person who gives or promises to give an undue advantage to another person or persons, with intention to induce a public servant to perform improperly a public function or activity, shall be punishable with imprisonment for a term which may extend to seven years or with fine or with both.", keywords: ["giving bribe", "bribing official", "corruption offence"] },
  { act: "Prevention of Corruption Act 1988", section: "13", title: "Criminal misconduct by a public servant", content: "A public servant is said to commit the offence of criminal misconduct if he dishonestly or fraudulently misappropriates or otherwise converts for his own use any property entrusted to him or under his control as a public servant or allows any other person so to do, or he intentionally enriches himself illicitly during the period of his office.", keywords: ["criminal misconduct", "misappropriation", "public servant corruption", "illicit enrichment"] },
  { act: "Narcotic Drugs and Psychotropic Substances Act 1985", section: "8", title: "Prohibition of certain operations", content: "No person shall cultivate any coca plant or gather any portion of coca plant, or cultivate the opium poppy or any cannabis plant, or produce, manufacture, possess, sell, purchase, transport, warehouse, use, consume, import inter-State, export inter-State, import into India, export from India or tranship any narcotic drug or psychotropic substance, except for medical or scientific purposes and in the manner and to the extent provided by the provisions of this Act.", keywords: ["drug prohibition", "narcotic drugs", "drug possession", "drug trafficking"] },
  { act: "Narcotic Drugs and Psychotropic Substances Act 1985", section: "20", title: "Punishment for contravention in relation to cannabis plant and cannabis", content: "Whoever, in contravention of any provision of this Act or any rule or order made or condition of licence granted thereunder, cultivates any cannabis plant or produces, manufactures, possesses, sells, purchases, transports, imports inter-State, exports inter-State or uses cannabis, shall be punishable with rigorous imprisonment for a term which may extend to ten years, and shall also be liable to fine which may extend to one lakh rupees for small quantity, and for commercial quantity with rigorous imprisonment not less than ten years extending to twenty years and fine not less than one lakh extending to two lakh rupees.", keywords: ["cannabis", "marijuana", "ganja", "drug punishment"] },
  { act: "Narcotic Drugs and Psychotropic Substances Act 1985", section: "21", title: "Punishment for contravention in relation to manufactured drugs", content: "Whoever, in contravention of any provision of this Act, manufactures, possesses, sells, purchases, transports, imports inter-State, exports inter-State or uses any manufactured drug or any preparation containing any manufactured drug shall be punishable with rigorous imprisonment for a term which shall not be less than ten years but which may extend to twenty years for commercial quantity, and shall also be liable to fine.", keywords: ["manufactured drugs", "heroin", "cocaine", "drug offence"] },
  { act: "Narcotic Drugs and Psychotropic Substances Act 1985", section: "27", title: "Punishment for consumption of any narcotic drug or psychotropic substance", content: "Whoever consumes any narcotic drug or psychotropic substance shall be punishable with imprisonment for a term which may extend to six months, or with fine which may extend to ten thousand rupees, or with both. If the narcotic drug or psychotropic substance consumed is cocaine, morphine, diacetyl-morphine or any other narcotic drug or psychotropic substance as may be specified, with imprisonment for a term which may extend to one year, or with fine which may extend to twenty thousand rupees, or with both.", keywords: ["drug consumption", "drug use", "narcotic consumption"] },
  { act: "Narcotic Drugs and Psychotropic Substances Act 1985", section: "37", title: "Offences to be cognizable and non-bailable", content: "Every offence punishable under this Act shall be cognizable. No person accused of an offence punishable for a term of imprisonment of five years or more under this Act shall be released on bail or on his own bond unless the Public Prosecutor has been given an opportunity to oppose the application for such release.", keywords: ["drug offence bail", "NDPS bail", "cognizable drug offence"] },
  { act: "Arms Act 1959", section: "3", title: "Licence for acquisition and possession of firearms and ammunition", content: "No person shall acquire, have in his possession, or carry any firearm or ammunition unless he holds in this behalf a licence issued in accordance with the provisions of this Act and the rules made thereunder.", keywords: ["arms licence", "gun licence", "firearm possession", "weapon licence"] },
  { act: "Arms Act 1959", section: "25", title: "Punishment for certain offences", content: "Whoever acquires, has in his possession or carries any firearm or ammunition in contravention of section 3 shall be punishable with imprisonment for a term which shall not be less than one year but which may extend to three years and shall also be liable to fine. Whoever acquires, has in his possession or carries any prohibited arms or prohibited ammunition shall be punishable with imprisonment for a term which shall not be less than five years but which may extend to ten years and shall also be liable to fine.", keywords: ["illegal arms", "unlicensed weapon", "arms punishment", "prohibited arms"] },
  { act: "Prevention of Money Laundering Act 2002", section: "3", title: "Offence of money laundering", content: "Whosoever directly or indirectly attempts to indulge or knowingly assists or knowingly is a party or is actually involved in any process or activity connected with the proceeds of crime including its concealment, possession, acquisition or use and projecting or claiming it as untainted property shall be guilty of offence of money-laundering.", keywords: ["money laundering", "proceeds of crime", "black money", "financial crime"] },
  { act: "Prevention of Money Laundering Act 2002", section: "4", title: "Punishment for money laundering", content: "Whoever commits the offence of money-laundering shall be punishable with rigorous imprisonment for a term which shall not be less than three years but which may extend to seven years and shall also be liable to fine. Where the proceeds of crime involved relate to any offence under the Narcotic Drugs and Psychotropic Substances Act, the punishment shall be rigorous imprisonment up to ten years.", keywords: ["money laundering punishment", "PMLA penalty", "financial crime punishment"] },
  { act: "Indian Succession Act 1925", section: "30", title: "Testamentary succession", content: "Every person of sound mind, not being a minor, may dispose of his property by will. A married woman may dispose of by will any property which she could alienate by her own act during her life.", keywords: ["will", "testament", "property will", "testamentary succession"] },
  { act: "Hindu Succession Act 1956", section: "6", title: "Devolution of interest in coparcenary property", content: "On and from the commencement of the Hindu Succession (Amendment) Act, 2005, in a Joint Hindu family governed by the Mitakshara law, the daughter of a coparcener shall by birth become a coparcener in her own right in the same manner as the son and have the same rights in the coparcenary property as she would have had if she had been a son.", keywords: ["coparcenary", "daughter rights", "Hindu succession", "property rights", "ancestral property"] },
  { act: "Hindu Succession Act 1956", section: "8", title: "General rules of succession in case of males", content: "The property of a male Hindu dying intestate shall devolve according to the provisions of this Chapter firstly upon the heirs specified in Class I of the Schedule, secondly if there is no heir of Class I then upon the heirs specified in Class II of the Schedule, thirdly if there is no heir of any of the two classes then upon the agnates of the deceased, and lastly if there is no agnate then upon the cognates of the deceased.", keywords: ["intestate succession", "male Hindu succession", "inheritance", "property inheritance"] },
  { act: "Hindu Succession Act 1956", section: "14", title: "Property of a female Hindu to be her absolute property", content: "Any property possessed by a female Hindu, whether acquired before or after the commencement of this Act, shall be held by her as full owner thereof and not as a limited owner.", keywords: ["female property rights", "woman property", "absolute ownership", "Hindu woman property"] },
  { act: "Hindu Succession Act 1956", section: "15", title: "General rules of succession in case of female Hindus", content: "The property of a female Hindu dying intestate shall devolve firstly upon the sons and daughters and the husband, secondly upon the heirs of the husband, thirdly upon the mother and father, fourthly upon the heirs of the father, and lastly upon the heirs of the mother.", keywords: ["female Hindu succession", "woman inheritance", "intestate female"] },
  { act: "Muslim Personal Law (Shariat) Application Act 1937", section: "2", title: "Application of Personal law to Muslims", content: "In all questions regarding intestate succession, special property of females including personal property inherited or obtained under contract or gift or any other provision of Personal Law, marriage, dissolution of marriage including talaq, ila, zihar, lian, khula and mubaraat, maintenance, dower, guardianship, gifts, trusts and trust properties, and wakfs, the rule of decision in cases where the parties are Muslims shall be the Muslim Personal Law (Shariat).", keywords: ["Muslim personal law", "Shariat", "talaq", "Muslim marriage", "Muslim inheritance"] },
  { act: "Special Marriage Act 1954", section: "4", title: "Conditions relating to solemnization of special marriages", content: "A marriage between any two persons may be solemnized under this Act if at the time of the marriage neither party has a spouse living, neither party is incapable of giving a valid consent to it in consequence of unsoundness of mind, the male has completed the age of twenty-one years and the female the age of eighteen years, and the parties are not within the degrees of prohibited relationship.", keywords: ["special marriage", "inter-caste marriage", "inter-religion marriage", "court marriage"] },
  { act: "Special Marriage Act 1954", section: "5", title: "Notice of intended marriage", content: "When a marriage is intended to be solemnized under this Act, the parties to the marriage shall give notice thereof in writing in the form specified in the Second Schedule to the Marriage Officer of the district in which at least one of the parties to the marriage has resided for a period of not less than thirty days immediately preceding the date on which such notice is given.", keywords: ["marriage notice", "court marriage procedure", "marriage registration"] },
  { act: "Special Marriage Act 1954", section: "27", title: "Divorce", content: "Any marriage solemnized under this Act may, on a petition presented by either the husband or the wife, be dissolved by a decree of divorce on the ground that the respondent has committed adultery, has deserted the petitioner for a continuous period of not less than two years, is undergoing a sentence of imprisonment for seven years or more, has treated the petitioner with cruelty, has been incurably of unsound mind for a continuous period of not less than three years, has been suffering from venereal disease in a communicable form, has been suffering from leprosy, has not been heard of as being alive for a period of seven years or more.", keywords: ["special marriage divorce", "court marriage divorce", "divorce grounds"] },
  { act: "Limitation Act 1963", section: "3", title: "Bar of limitation", content: "Every suit instituted, appeal preferred, and application made after the prescribed period shall be dismissed although limitation has not been set up as a defence.", keywords: ["limitation period", "time bar", "statute of limitations"] },
  { act: "Limitation Act 1963", section: "5", title: "Extension of prescribed period in certain cases", content: "Any appeal or any application, other than an application under any of the provisions of Order XXI of the Code of Civil Procedure, 1908, may be admitted after the prescribed period if the appellant or the applicant satisfies the court that he had sufficient cause for not preferring the appeal or making the application within such period.", keywords: ["condonation of delay", "extension of time", "sufficient cause"] },
  { act: "Transfer of Property Act 1882", section: "5", title: "Transfer of property defined", content: "Transfer of property means an act by which a living person conveys property, in present or in future, to one or more other living persons, or to himself and one or more other living persons; and to transfer property is to perform such act.", keywords: ["property transfer", "conveyance", "transfer of property"] },
  { act: "Transfer of Property Act 1882", section: "54", title: "Sale defined", content: "Sale is a transfer of ownership in exchange for a price paid or promised or part-paid and part-promised. Such transfer, in the case of tangible immoveable property of the value of one hundred rupees and upwards, or in the case of a reversion or other intangible thing, can be made only by a registered instrument.", keywords: ["property sale", "sale deed", "registered instrument", "immovable property sale"] },
  { act: "Transfer of Property Act 1882", section: "58", title: "Mortgage defined", content: "A mortgage is the transfer of an interest in specific immoveable property for the purpose of securing the payment of money advanced or to be advanced by way of loan, an existing or future debt, or the performance of an engagement which may give rise to a pecuniary liability.", keywords: ["mortgage", "property mortgage", "home loan", "secured loan"] },
  { act: "Transfer of Property Act 1882", section: "105", title: "Lease defined", content: "A lease of immoveable property is a transfer of a right to enjoy such property, made for a certain time, express or implied, or in perpetuity, in consideration of a price paid or promised, or of money, a share of crops, service or any other thing of value, to be rendered periodically or on specified occasions to the transferor by the transferee, who accepts the transfer on such terms.", keywords: ["lease", "rent agreement", "tenancy", "lease agreement"] },
  { act: "Transfer of Property Act 1882", section: "106", title: "Duration of certain leases in absence of written contract or local usage", content: "In the absence of a contract or local law or usage to the contrary, a lease of immoveable property for agricultural or manufacturing purposes shall be deemed to be a lease from year to year, terminable, on the part of either lessor or lessee, by six months' notice; and a lease of immoveable property for any other purpose shall be deemed to be a lease from month to month, terminable, on the part of either lessor or lessee, by fifteen days' notice.", keywords: ["lease termination", "notice period", "tenant notice", "landlord notice"] },
  { act: "Registration Act 1908", section: "17", title: "Documents of which registration is compulsory", content: "The following documents shall be registered if the property to which they relate is situate in a district in which, and if they have been executed on or after the date on which, this Act came or comes into force: instruments of gift of immoveable property, other non-testamentary instruments which purport or operate to create, declare, assign, limit or extinguish any right, title or interest to or in immoveable property where the value of the property is one hundred rupees and upwards, non-testamentary instruments which acknowledge the receipt or payment of any consideration on account of the creation, declaration, assignment, limitation or extinction of any such right, title or interest, and leases of immoveable property from year to year or for any term exceeding one year.", keywords: ["compulsory registration", "property registration", "document registration", "sale deed registration"] },
  { act: "Indian Stamp Act 1899", section: "3", title: "Instruments chargeable with duty", content: "Every instrument mentioned in the Schedule to this Act which, not having been previously executed by any person, is executed in India on or after the first day of July, 1899, shall be chargeable with duty of the amount indicated in that Schedule as the proper duty therefor.", keywords: ["stamp duty", "instrument duty", "property stamp duty"] },
  { act: "Arbitration and Conciliation Act 1996", section: "7", title: "Arbitration agreement", content: "An arbitration agreement means an agreement by the parties to submit to arbitration all or certain disputes which have arisen or which may arise between them in respect of a defined legal relationship, whether contractual or not. An arbitration agreement may be in the form of an arbitration clause in a contract or in the form of a separate agreement.", keywords: ["arbitration", "arbitration agreement", "dispute resolution", "arbitration clause"] },
  { act: "Arbitration and Conciliation Act 1996", section: "9", title: "Interim measures by Court", content: "A party may, before or during arbitral proceedings or at any time after the making of the arbitral award but before it is enforced, apply to a Court for an interim measure of protection including the preservation of any goods which are the subject matter of the arbitration agreement, securing the amount in dispute, the detention, preservation or inspection of any property or thing which is the subject matter of the dispute.", keywords: ["interim relief", "arbitration court", "interim measures", "property preservation"] },
  { act: "Arbitration and Conciliation Act 1996", section: "34", title: "Application for setting aside arbitral award", content: "Recourse to a Court against an arbitral award may be made only by an application for setting aside such award. An arbitral award may be set aside by the Court only if the party making the application furnishes proof that a party was under some incapacity, or the arbitration agreement is not valid under the law, or the party was not given proper notice, or the award deals with a dispute not contemplated by the terms of the submission to arbitration.", keywords: ["setting aside award", "challenge arbitration", "arbitral award appeal"] },
  { act: "Arbitration and Conciliation Act 1996", section: "36", title: "Enforcement of arbitral award", content: "Where the time for making an application to set aside the arbitral award has expired, or such application having been made, it has been refused, the award shall be enforced in accordance with the provisions of the Code of Civil Procedure, 1908, in the same manner as if it were a decree of the Court.", keywords: ["arbitration enforcement", "award enforcement", "arbitral decree"] },
  { act: "Competition Act 2002", section: "3", title: "Anti-competitive agreements", content: "No enterprise or association of enterprises or person or association of persons shall enter into any agreement in respect of production, supply, distribution, storage, acquisition or control of goods or provision of services, which causes or is likely to cause an appreciable adverse effect on competition within India.", keywords: ["anti-competitive", "cartel", "price fixing", "competition law"] },
  { act: "Competition Act 2002", section: "4", title: "Abuse of dominant position", content: "No enterprise or group shall abuse its dominant position. There shall be an abuse of dominant position if an enterprise or a group directly or indirectly imposes unfair or discriminatory condition in purchase or sale of goods or service, or limits or restricts production of goods or provision of services or market therefor, or indulges in practice or practices resulting in denial of market access.", keywords: ["dominant position", "monopoly", "market abuse", "unfair competition"] },
  { act: "Companies Act 2013", section: "2(20)", title: "Company defined", content: "Company means a company incorporated under this Act or under any previous company law.", keywords: ["company", "company definition", "incorporation"] },
  { act: "Companies Act 2013", section: "7", title: "Incorporation of company", content: "There shall be filed with the Registrar an application for registration of the company along with the memorandum and articles of the company, a declaration by each subscriber to the memorandum and from the first directors, an affidavit from each of the subscribers to the memorandum, the address for correspondence, and the particulars of every subscriber.", keywords: ["company incorporation", "company registration", "memorandum", "articles of association"] },
  { act: "Companies Act 2013", section: "149", title: "Company to have Board of Directors", content: "Every company shall have a Board of Directors consisting of individuals as directors. Every company shall have a minimum number of three directors in the case of a public company, two directors in the case of a private company, and one director in the case of a One Person Company.", keywords: ["board of directors", "company directors", "minimum directors"] },
  { act: "Companies Act 2013", section: "166", title: "Duties of directors", content: "A director of a company shall act in accordance with the articles of the company, act in good faith in order to promote the objects of the company for the benefit of its members as a whole, and in the best interests of the company, its employees, the shareholders, the community and for the protection of environment, exercise his duties with due and reasonable care, skill and diligence, shall not involve in a situation in which he may have a direct or indirect interest that conflicts with the interest of the company, shall not achieve or attempt to achieve any undue gain or advantage either to himself or to his relatives, partners, or associates.", keywords: ["director duties", "fiduciary duty", "corporate governance", "director responsibility"] },
  { act: "Companies Act 2013", section: "447", title: "Punishment for fraud", content: "Without prejudice to any liability including repayment of any debt under this Act or any other law for the time being in force, any person who is found to be guilty of fraud involving an amount of at least ten lakh rupees or one per cent of the turnover of the company, whichever is lower, shall be punishable with imprisonment for a term which shall not be less than six months but which may extend to ten years and shall also be liable to fine which shall not be less than the amount involved in the fraud, but which may extend to three times the amount involved in the fraud.", keywords: ["corporate fraud", "company fraud", "fraud punishment", "financial fraud"] },
];

// Insert in batches of 20
async function insertData() {
  console.log('Total laws to insert:', laws.length);
  const batchSize = 20;
  let inserted = 0;

  for (let i = 0; i < laws.length; i += batchSize) {
    const batch = laws.slice(i, i + batchSize);
    const values = [];
    const placeholders = batch.map((law, index) => {
      const offset = index * 5;
      values.push(law.act, law.section, law.title, law.content, law.keywords);
      return `($${offset + 1}, $${offset + 2}, $${offset + 3}, $${offset + 4}, $${offset + 5})`;
    });

    try {
      await db.query(
        `
          INSERT INTO laws (act, section, title, content, keywords)
          VALUES ${placeholders.join(', ')}
        `,
        values
      );
      inserted += batch.length;
      console.log('Inserted batch:', i, '-', i + batch.length - 1, '(' + inserted + '/' + laws.length + ')');
    } catch (error) {
      console.error('Batch insert error at index', i, ':', error.message);
    }
  }

  console.log('Done! Inserted', inserted, 'laws.');
  process.exit(0);
}

insertData().catch(err => {
  console.error('Error:', err);
  process.exit(1);
});
